      className={`rounded-xl border border-border bg-surface shadow-[0_1px_2px_rgba(16,24,40,0.04),0_1px_3px_rgba(16,24,40,0.06)] ${
        padding ? "p-5" : ""
      } ${className}`}
    >
      {children}
