import { ReactNode } from "react";

interface StatCardProps {
  label: string;
  value: ReactNode;
  hint?: string;
  trend?: { value: string; positive?: boolean };
  className?: string;
  children?: ReactNode;
}

export default function StatCard({ label, value, hint, trend, className = "", children }: StatCardProps) {
  return (
    <div
      className={`flex flex-col rounded-xl border border-border bg-surface p-5 shadow-[0_1px_2px_rgba(16,24,40,0.04),0_1px_3px_rgba(16,24,40,0.06)] ${className}`}
    >
      <p className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">{label}</p>
      <p className="mt-2 font-display text-[1.75rem] font-semibold leading-none text-ink">{value}</p>
      <div className="mt-2 flex items-center gap-2">
        {trend && (
          <span
            className={`text-[0.8125rem] font-medium ${
              trend.positive === false ? "text-danger" : "text-success"
            }`}
          >
            {trend.value}
          </span>
        )}
        {hint && <span className="text-[0.8125rem] text-muted">{hint}</span>}
      </div>
      {children && <div className="mt-3">{children}</div>}
    </div>
  );
}

import { ReactNode } from "react";

export type BadgeTone = "neutral" | "primary" | "accent" | "success" | "warning" | "danger";

const toneClasses: Record<BadgeTone, string> = {
  neutral: "bg-surfaceMuted text-muted",
  primary: "bg-primary/10 text-primary",
  accent: "bg-accent/10 text-accent",
  success: "bg-success/10 text-success",
  warning: "bg-warning/10 text-warning",
  danger: "bg-danger/10 text-danger",
};

export default function Badge({
  children,
  tone = "neutral",
  className = "",
}: {
  children: ReactNode;
  tone?: BadgeTone;
  className?: string;
}) {
  return (
    <span
      className={`inline-flex items-center whitespace-nowrap rounded-full px-2 py-[2px] text-[0.75rem] font-medium ${toneClasses[tone]} ${className}`}
    >
      {children}
    </span>
  );
}

export function statusTone(status: string): BadgeTone {
  switch (status) {
    case "done":
    case "completed":
    case "income":
      return "success";
    case "in_progress":
    case "active":
      return "primary";
    case "todo":
    case "planned":
      return "neutral";
    case "archived":
    case "abandoned":
      return "danger";
    default:
      return "neutral";
  }
}

export function priorityTone(priority: string): BadgeTone {
  if (priority === "high") return "danger";
  if (priority === "medium") return "warning";
  return "neutral";
}

export function labelize(value: string): string {
  return value
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

import { ButtonHTMLAttributes, ReactNode } from "react";

type Variant = "primary" | "secondary" | "ghost" | "danger";
type Size = "sm" | "md";

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
  children: ReactNode;
  loading?: boolean;
}

const variants: Record<Variant, string> = {
  primary: "bg-primary text-primary-ink hover:bg-primary/90",
  secondary: "border border-border bg-surface text-ink hover:bg-surfaceMuted",
  ghost: "text-ink hover:bg-surfaceMuted",
  danger: "bg-danger text-danger-ink hover:bg-danger/90",
};

const sizes: Record<Size, string> = {
  sm: "px-3 py-1.5 text-[0.8125rem]",
  md: "px-4 py-2 text-[0.875rem]",
};

export default function Button({
  variant = "primary",
  size = "md",
  children,
  className = "",
  loading = false,
  disabled,
  type = "button",
  ...rest
}: ButtonProps) {
  return (
    <button
      type={type}
      disabled={disabled || loading}
      className={`inline-flex items-center justify-center gap-2 rounded-lg font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 disabled:cursor-not-allowed disabled:opacity-60 ${variants[variant]} ${sizes[size]} ${className}`}
      {...rest}
    >
      {loading && (
        <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <circle cx="12" cy="12" r="9" stroke="currentColor" strokeOpacity="0.25" strokeWidth="3" />
          <path d="M21 12a9 9 0 0 0-9-9" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
        </svg>
      )}
      {children}
    </button>
  );
}

import { ReactNode } from "react";

