import datetime
from typing import List, Optional

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field
from sqlalchemy.orm import Session

import models
from auth import get_current_user
from database import get_db

router = APIRouter(prefix="/api/goals", tags=["goals"])


class GoalIn(BaseModel):
    title: str = Field(min_length=1, max_length=200)
    category: Optional[str] = "personal"
    description: Optional[str] = None
    target_date: Optional[datetime.date] = None
    progress: Optional[int] = 0
    status: Optional[str] = "active"


class GoalUpdate(BaseModel):
    title: Optional[str] = None
    category: Optional[str] = None
    description: Optional[str] = None
    target_date: Optional[datetime.date] = None
    progress: Optional[int] = None
    status: Optional[str] = None


class GoalOut(BaseModel):
    id: int
    title: str
    category: str
    description: Optional[str] = None
    target_date: Optional[datetime.date] = None
    progress: int
    status: str

    class Config:
        from_attributes = True


def _clamp(value: Optional[int], low: int, high: int, default: int = 0) -> int:
    if value is None:
        return default
    return max(low, min(high, int(value)))


def _owned(db: Session, user: models.User, goal_id: int) -> models.Goal:
    goal = (
        db.query(models.Goal)
        .filter(models.Goal.id == goal_id, models.Goal.user_id == user.id)
        .first()
    )
    if not goal:
        raise HTTPException(status_code=404, detail="Goal not found")
    return goal


@router.get("", response_model=List[GoalOut])
def list_goals(
    category: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    q = db.query(models.Goal).filter(models.Goal.user_id == user.id)
    if category:
        q = q.filter(models.Goal.category == category)
    if status:
        q = q.filter(models.Goal.status == status)
    return q.order_by(models.Goal.id.desc()).all()


@router.post("", response_model=GoalOut)
def create_goal(
    payload: GoalIn,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    goal = models.Goal(
        user_id=user.id,
        title=payload.title.strip(),
        category=payload.category or "personal",
        description=payload.description,
        target_date=payload.target_date,
        progress=_clamp(payload.progress, 0, 100, 0),
        status=payload.status or "active",
    )
    if goal.progress >= 100 and goal.status == "active":
        goal.status = "completed"
    db.add(goal)
    db.commit()
    db.refresh(goal)
    return goal


@router.get("/{goal_id}", response_model=GoalOut)
def get_goal(goal_id: int, db: Session = Depends(get_db), user: models.User = Depends(get_current_user)):
    return _owned(db, user, goal_id)


@router.put("/{goal_id}", response_model=GoalOut)
def update_goal(
    goal_id: int,
    payload: GoalUpdate,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    goal = _owned(db, user, goal_id)
    data = payload.model_dump(exclude_unset=True)
    if "progress" in data and data["progress"] is not None:
        data["progress"] = _clamp(data["progress"], 0, 100, goal.progress)
    for key, value in data.items():
        if value is not None or key in ("description", "target_date"):
            setattr(goal, key, value)
    if goal.progress >= 100:
        goal.status = "completed"
    db.commit()
    db.refresh(goal)
    return goal


@router.delete("/{goal_id}")
def delete_goal(goal_id: int, db: Session = Depends(get_db), user: models.User = Depends(get_current_user)):
    goal = _owned(db, user, goal_id)
    db.delete(goal)
    db.commit()
    return {"ok": True, "deleted_id": goal_id}

import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { format } from "date-fns";
import { ArrowRight, CheckCircle2, Clock } from "lucide-react";
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
} from "recharts";
import { api } from "../lib/api";
import { useAuth } from "../context/AuthContext";
import type { AnalyticsOverview, CalendarEvent, Transaction } from "../types";
import StatCard from "../components/ui/StatCard";
import Card, { CardHeader } from "../components/ui/Card";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

function currency(n: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(n);
}

function ProgressBar({ value, tone = "primary" }: { value: number; tone?: "primary" | "accent" | "success" }) {
  const bg = tone === "accent" ? "bg-accent" : tone === "success" ? "bg-success" : "bg-primary";
  return (
    <div className="h-2 w-full overflow-hidden rounded-full bg-surfaceMuted">
      <div className={`h-full rounded-full ${bg}`} style={{ width: `${Math.min(100, Math.max(0, value))}%` }} />
    </div>
  );
}

export default function Dashboard() {
  const { user } = useAuth();
  const [data, setData] = useState<AnalyticsOverview | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [overview, tx] = await Promise.all([
        api.get<AnalyticsOverview>("/analytics/overview"),
        api.get<Transaction[]>("/finance/transactions").catch(() => ({ data: [] as Transaction[] })),
      ]);
      setData(overview.data);
      setTransactions(tx.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your dashboard.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  const cashflowSeries = useMemo(() => {
    const byMonth = new Map<string, { month: string; income: number; expense: number }>();
    const sorted = [...transactions].sort((a, b) => a.date.localeCompare(b.date));
    for (const t of sorted) {
      const key = t.date.slice(0, 7);
      const label = format(new Date(`${key}-01T00:00:00`), "MMM");
      const row = byMonth.get(key) ?? { month: label, income: 0, expense: 0 };
      if (t.type === "income") row.income += t.amount;
      else row.expense += t.amount;
      byMonth.set(key, row);
    }
    return Array.from(byMonth.values()).slice(-6);
  }, [transactions]);

  const completionRate =
    data && data.tasks_total_this_week > 0
      ? Math.round((data.tasks_completed_this_week / data.tasks_total_this_week) * 100)
      : 0;

  const today = format(new Date(), "EEEE, d MMMM yyyy");
  const greeting = (() => {
    const h = new Date().getHours();
    if (h < 12) return "Good morning";
    if (h < 18) return "Good afternoon";
    return "Good evening";
  })();

  if (loading) {
    return (
      <div className="grid gap-4 md:grid-cols-4">
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <Card key={i} className={i < 2 ? "md:col-span-2" : ""}>
            <LoadingBlock />
          </Card>
        ))}
      </div>
    );
  }

  if (error) return <ErrorBlock message={error} onRetry={load} />;
  if (!data) return <ErrorBlock message="No dashboard data available." onRetry={load} />;

  return (
    <div className="space-y-5">
      <div>
        <h2 className="font-display text-[1.5rem] font-semibold text-ink">
          {greeting}, {user?.name?.split(" ")[0] || "there"}
        </h2>
        <p className="mt-1 text-[0.875rem] text-muted">{today} — here is everything in one view.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        {/* Large tile: tasks this week */}
        <Card className="md:col-span-2 md:row-span-2">
          <CardHeader
            title="Tasks this week"
            subtitle="Completed against everything due in the current week"
            action={
              <Link to="/tasks" className="flex items-center gap-1 text-[0.8125rem] font-medium text-primary hover:underline">
                Open tasks <ArrowRight className="h-3.5 w-3.5" strokeWidth={2} />
              </Link>
            }
          />
          <div className="flex items-end gap-3">
            <span className="font-display text-[3rem] font-semibold leading-none text-ink">
              {data.tasks_completed_this_week}
            </span>
            <span className="pb-1.5 text-[0.875rem] text-muted">of {data.tasks_total_this_week} tasks</span>
          </div>
          <div className="mt-4">
            <ProgressBar value={completionRate} />
            <p className="mt-2 text-[0.8125rem] text-muted">{completionRate}% completion rate this week</p>
          </div>
          <div className="mt-6 grid grid-cols-2 gap-3">
            <div className="rounded-lg border border-border bg-surfaceMuted/50 p-3">
              <p className="flex items-center gap-1.5 text-[0.75rem] text-muted">
                <CheckCircle2 className="h-3.5 w-3.5" strokeWidth={2} /> Done
              </p>
              <p className="mt-1 font-display text-[1.125rem] font-semibold text-ink">
                {data.tasks_completed_this_week}
              </p>
            </div>
            <div className="rounded-lg border border-border bg-surfaceMuted/50 p-3">
              <p className="flex items-center gap-1.5 text-[0.75rem] text-muted">
                <Clock className="h-3.5 w-3.5" strokeWidth={2} /> Open
              </p>
              <p className="mt-1 font-display text-[1.125rem] font-semibold text-ink">
                {Math.max(0, data.tasks_total_this_week - data.tasks_completed_this_week)}
              </p>
            </div>
          </div>
        </Card>

        <StatCard
          label="Month net cashflow"
          value={currency(data.month_net_cashflow)}
          trend={{
            value: data.month_net_cashflow >= 0 ? "positive" : "negative",
            positive: data.month_net_cashflow >= 0,
          }}
          hint="income − expenses"
        />
        <StatCard label="Habit completion" value={`${Math.round(data.habit_avg_completion)}%`} hint="average, last 30 days" />
        <StatCard label="Workouts this week" value={data.workouts_this_week} hint="logged sessions" />
        <StatCard label="Events this week" value={data.events_this_week} hint="scheduled" />

        {/* Cashflow chart */}
        <Card className="md:col-span-2">
          <CardHeader title="Cashflow" subtitle="Income and expenses by month" />
          {cashflowSeries.length === 0 ? (
            <EmptyState title="No transactions yet" description="Record income or an expense to see your cashflow trend." />
          ) : (
            <div className="h-52">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={cashflowSeries} margin={{ top: 4, right: 4, bottom: 0, left: -18 }}>
                  <defs>
                    <linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="var(--success)" stopOpacity={0.28} />
                      <stop offset="100%" stopColor="var(--success)" stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="expenseFill" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="var(--danger)" stopOpacity={0.24} />
                      <stop offset="100%" stopColor="var(--danger)" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid stroke="var(--border)" vertical={false} />
                  <XAxis dataKey="month" tick={{ fontSize: 11, fill: "var(--muted)" }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: "var(--muted)" }} axisLine={false} tickLine={false} />
                  <Tooltip
                    contentStyle={{
                      borderRadius: 12,
                      border: "1px solid var(--border)",
                      fontSize: 12,
                      boxShadow: "0 4px 12px rgba(16,24,40,0.08)",
                    }}
                    formatter={(v: number, n: string) => [currency(v), n === "income" ? "Income" : "Expense"]}
                  />
                  <Area type="monotone" dataKey="income" stroke="var(--success)" strokeWidth={2} fill="url(#incomeFill)" />
                  <Area type="monotone" dataKey="expense" stroke="var(--danger)" strokeWidth={2} fill="url(#expenseFill)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          )}
        </Card>

        {/* Goals */}
        <Card>
          <CardHeader
            title="Goals"
            action={
              <Link to="/goals" className="text-[0.8125rem] font-medium text-primary hover:underline">
                View
              </Link>
            }
          />
          <p className="font-display text-[2rem] font-semibold leading-none text-ink">{data.avg_goal_progress}%</p>
          <p className="mt-1 text-[0.8125rem] text-muted">average progress</p>
          <div className="mt-4">
            <ProgressBar value={data.avg_goal_progress} tone="accent" />
          </div>
          <p className="mt-3 text-[0.8125rem] text-muted">{data.active_goals_count} active goals</p>
        </Card>

        <StatCard label="Habits tracked" value={`${Math.round(data.habit_avg_completion)}%`} hint="rolling average" />

        {/* Upcoming events */}
        <Card className="md:col-span-4">
          <CardHeader
            title="Upcoming events"
            subtitle="Next items on your calendar"
            action={
              <Link to="/calendar" className="text-[0.8125rem] font-medium text-primary hover:underline">
                Open calendar
              </Link>
            }
          />
          {data.upcoming_events.length === 0 ? (
            <EmptyState title="Nothing scheduled" description="Add an event to your calendar and it will show up here." />
          ) : (
            <ul className="divide-y divide-border">
              {data.upcoming_events.slice(0, 6).map((event: CalendarEvent) => (
                <li key={event.id} className="flex items-center gap-3 py-2.5">
                  <div className="w-14 shrink-0">
                    <p className="text-[0.6875rem] uppercase tracking-wide text-muted">
                      {format(new Date(event.start_time), "MMM")}
                    </p>
                    <p className="font-display text-[1.0625rem] font-semibold text-ink">
                      {format(new Date(event.start_time), "d")}
                    </p>
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-[0.875rem] font-medium text-ink">{event.title}</p>
                    <p className="truncate text-[0.75rem] text-muted">
                      {format(new Date(event.start_time), "HH:mm")} · {event.category}
                      {event.location ? ` · ${event.location}` : ""}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Plus, Pencil, Trash2 } from "lucide-react";
import { api } from "../lib/api";
import type { Project, Task } from "../types";
import Card from "../components/ui/Card";
import Badge, { labelize, statusTone } from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

const COLORS = ["#4338CA", "#0D9488", "#16A34A", "#D97706", "#DC2626", "#6B7280"];

interface FormState {
  name: string;
  description: string;
  status: Project["status"];
  color: string;
}

const emptyForm: FormState = { name: "", description: "", status: "active", color: COLORS[0] };

export default function ProjectsPage() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const [editing, setEditing] = useState<Project | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [confirmId, setConfirmId] = useState<number | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [p, t] = await Promise.all([
        api.get<Project[]>("/projects"),
        api.get<Task[]>("/tasks").catch(() => ({ data: [] as Task[] })),
      ]);
      setProjects(p.data);
      setTasks(t.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your projects.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setFormError(null);
    setPanelOpen(true);
  }

  function openEdit(project: Project) {
    setEditing(project);
    setForm({
      name: project.name,
      description: project.description ?? "",
      status: project.status,
      color: project.color || COLORS[0],
    });
    setFormError(null);
    setPanelOpen(true);
  }

  async function handleSubmit() {
    if (!form.name.trim()) {
      setFormError("Give the project a name.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      name: form.name.trim(),
      description: form.description.trim() || null,
      status: form.status,
      color: form.color,
    };
    try {
      if (editing) {
        const res = await api.put<Project>(`/projects/${editing.id}`, payload);
        setProjects((prev) => prev.map((p) => (p.id === editing.id ? res.data : p)));
      } else {
        const res = await api.post<Project>("/projects", payload);
        setProjects((prev) => [res.data, ...prev]);
      }
      setPanelOpen(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the project.");
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(id: number) {
    try {
      await api.delete(`/projects/${id}`);
      setProjects((prev) => prev.filter((p) => p.id !== id));
      setConfirmId(null);
    } catch {
      setConfirmId(null);
    }
  }

  function taskCount(projectId: number) {
    const list = tasks.filter((t) => t.project_id === projectId);
    const done = list.filter((t) => t.status === "done").length;
    return { total: list.length, done };
  }

  return (
    <div>
      <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-[0.875rem] text-muted">Group your tasks into projects and track how far each one has come.</p>
        </div>
        <Button onClick={openCreate}>
          <Plus className="h-4 w-4" strokeWidth={2} /> New project
        </Button>
      </div>

      {loading ? (
        <Card>
          <LoadingBlock label="Loading projects" />
        </Card>
      ) : error ? (
        <ErrorBlock message={error} onRetry={load} />
      ) : projects.length === 0 ? (
        <EmptyState
          title="No projects yet"
          description="Create your first project to start grouping tasks around the things you are actually working on."
          action={<Button onClick={openCreate}>Create a project</Button>}
        />
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {projects.map((project) => {
            const counts = taskCount(project.id);
            const pct = counts.total ? Math.round((counts.done / counts.total) * 100) : 0;
            return (
              <Card key={project.id} className="flex flex-col">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex min-w-0 items-center gap-2">
                    <span
                      className="h-2.5 w-2.5 shrink-0 rounded-full"
                      style={{ backgroundColor: project.color }}
                      aria-hidden="true"
                    />
                    <h3 className="truncate font-display text-[1.0625rem] font-semibold text-ink">{project.name}</h3>
                  </div>
                  <Badge tone={statusTone(project.status)}>{labelize(project.status)}</Badge>
                </div>
                <p className="mt-2 line-clamp-2 text-[0.875rem] leading-relaxed text-muted">
                  {project.description || "No description yet."}
                </p>
                <div className="mt-4">
                  <div className="h-2 w-full overflow-hidden rounded-full bg-surfaceMuted">
                    <div
                      className="h-full rounded-full bg-primary"
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                  <p className="mt-1.5 text-[0.75rem] text-muted">
                    {counts.done} of {counts.total} tasks done · {pct}%
                  </p>
                </div>
                <div className="mt-4 flex items-center gap-2 border-t border-border pt-3">
                  <Button variant="ghost" size="sm" onClick={() => openEdit(project)}>
                    <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} /> Edit
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-danger hover:bg-danger/10"
                    onClick={() => setConfirmId(project.id)}
                  >
                    <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} /> Delete
                  </Button>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      <Modal
        open={panelOpen}
        onClose={() => setPanelOpen(false)}
        title={editing ? "Edit project" : "New project"}
        subtitle="Projects group tasks and give them a home."
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setPanelOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} loading={saving}>
              {editing ? "Save changes" : "Create project"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Project name">
          <input
            className={inputClass}
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            placeholder="e.g. Personal website rebuild"
          />
        </Field>
        <Field label="Description" hint="Optional — what this project is about.">
          <textarea
            className={`${inputClass} min-h-[100px] resize-y`}
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
            placeholder="A short description"
          />
        </Field>
        <Field label="Status">
          <select
            className={inputClass}
            value={form.status}
            onChange={(e) => setForm({ ...form, status: e.target.value as Project["status"] })}
          >
            <option value="active">Active</option>
            <option value="completed">Completed</option>
            <option value="archived">Archived</option>
          </select>
        </Field>
        <Field label="Colour">
          <div className="flex flex-wrap gap-2">
            {COLORS.map((c) => (
              <button
                key={c}
                type="button"
                aria-label={`Use colour ${c}`}
                aria-pressed={form.color === c}
                onClick={() => setForm({ ...form, color: c })}
                className={`h-7 w-7 rounded-full border-2 transition-transform ${
                  form.color === c ? "border-ink scale-110" : "border-transparent"
                }`}
                style={{ backgroundColor: c }}
              />
            ))}
          </div>
        </Field>
      </Modal>

      <Modal
        open={confirmId !== null}
        onClose={() => setConfirmId(null)}
        title="Delete project"
        subtitle="This also removes its tasks. This cannot be undone."
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirmId(null)}>
              Keep it
            </Button>
            <Button variant="danger" onClick={() => confirmId !== null && handleDelete(confirmId)}>
              Delete project
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">
          The project and every task inside it will be permanently removed from your workspace.
        </p>
      </Modal>
    </div>
  );
}

import os
import uuid
from typing import Optional

from fastapi import APIRouter, Depends, File, HTTPException, UploadFile
from pydantic import BaseModel, EmailStr, Field
from sqlalchemy.orm import Session

import models
from auth import get_current_user, hash_password, require_owner, verify_password
from database import get_db

router = APIRouter(prefix="/api/settings", tags=["settings"])

UPLOAD_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "uploads")
ALLOWED_IMAGE_EXT = {".png", ".jpg", ".jpeg", ".webp", ".svg", ".gif"}


class ProfileOut(BaseModel):
    id: int
    email: str
    name: str
    role: str

    class Config:
        from_attributes = True


class ProfileUpdate(BaseModel):
    name: Optional[str] = None
    email: Optional[EmailStr] = None


class PasswordChange(BaseModel):
    old_password: str
    new_password: str = Field(min_length=6, max_length=128)


class SiteSettingsOut(BaseModel):
    site_title: str
    tagline: str
    logo_url: Optional[str] = None

    class Config:
        from_attributes = True


class SiteSettingsUpdate(BaseModel):
    site_title: Optional[str] = None
    tagline: Optional[str] = None


def _get_or_create_site(db: Session) -> models.SiteSettings:
    site = db.query(models.SiteSettings).first()
    if not site:
        site = models.SiteSettings(
            site_title="Life OS",
            tagline="Organize every part of your life, manually and mindfully.",
        )
        db.add(site)
        db.commit()
        db.refresh(site)
    return site


# ---------------- profile ----------------
@router.get("/profile", response_model=ProfileOut)
def get_profile(user: models.User = Depends(get_current_user)):
    return ProfileOut.model_validate(user)


@router.put("/profile", response_model=ProfileOut)
def update_profile(
    payload: ProfileUpdate,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    data = payload.model_dump(exclude_unset=True)
    if data.get("email"):
        email = data["email"].strip().lower()
        clash = (
            db.query(models.User)
            .filter(models.User.email == email, models.User.id != user.id)
            .first()
        )
        if clash:
            raise HTTPException(status_code=400, detail="That email is already in use")
        user.email = email
    if data.get("name"):
        user.name = data["name"].strip()
    db.commit()
    db.refresh(user)
    return ProfileOut.model_validate(user)


@router.put("/password")
def change_password(
    payload: PasswordChange,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    if not verify_password(payload.old_password, user.password_hash):
        raise HTTPException(status_code=400, detail="Current password is incorrect")
    user.password_hash = hash_password(payload.new_password)
    db.commit()
    return {"ok": True, "message": "Password updated"}


# ---------------- site settings (public GET) ----------------
@router.get("/site", response_model=SiteSettingsOut)
def get_site(db: Session = Depends(get_db)):
    return SiteSettingsOut.model_validate(_get_or_create_site(db))


@router.put("/site", response_model=SiteSettingsOut)
def update_site(
    payload: SiteSettingsUpdate,
    db: Session = Depends(get_db),
    _owner: models.User = Depends(require_owner),
):
    site = _get_or_create_site(db)
    data = payload.model_dump(exclude_unset=True)
    if data.get("site_title"):
        site.site_title = data["site_title"].strip()
    if data.get("tagline") is not None and data.get("tagline") != "":
        site.tagline = data["tagline"].strip()
    db.commit()
    db.refresh(site)
    return SiteSettingsOut.model_validate(site)


@router.post("/site/logo", response_model=SiteSettingsOut)
async def upload_logo(
    file: UploadFile = File(...),
    db: Session = Depends(get_db),
    _owner: models.User = Depends(require_owner),
):
    ext = os.path.splitext(file.filename or "")[1].lower()
    if ext not in ALLOWED_IMAGE_EXT:
        raise HTTPException(status_code=400, detail="Logo must be a PNG, JPG, SVG, GIF or WebP image")
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    filename = f"logo-{uuid.uuid4().hex}{ext}"
    dest = os.path.join(UPLOAD_DIR, filename)
    with open(dest, "wb") as out:
        out.write(await file.read())

    site = _get_or_create_site(db)
    site.logo_url = f"/api/uploads/{filename}"
    db.commit()
    db.refresh(site)
    return SiteSettingsOut.model_validate(site)

import { useEffect, useMemo, useState } from "react";
import { format, isBefore, startOfDay } from "date-fns";
import { Plus, Pencil, Trash2, Search } from "lucide-react";
import { api } from "../lib/api";
import type { Project, Task } from "../types";
import Card from "../components/ui/Card";
import Badge, { labelize, priorityTone, statusTone } from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

interface FormState {
  title: string;
  description: string;
  project_id: string;
  status: Task["status"];
  priority: Task["priority"];
  due_date: string;
}

const emptyForm: FormState = {
  title: "",
  description: "",
  project_id: "",
  status: "todo",
  priority: "medium",
  due_date: "",
};

export default function TasksPage() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const [editing, setEditing] = useState<Task | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [confirmId, setConfirmId] = useState<number | null>(null);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [priorityFilter, setPriorityFilter] = useState("all");
  const [projectFilter, setProjectFilter] = useState("all");
  const [sortBy, setSortBy] = useState<"created" | "due" | "priority">("created");

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [t, p] = await Promise.all([api.get<Task[]>("/tasks"), api.get<Project[]>("/projects").catch(() => ({ data: [] as Project[] }))]);
      setTasks(t.data);
      setProjects(p.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your tasks.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  const projectName = (id: number | null) => projects.find((p) => p.id === id)?.name ?? "No project";

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setFormError(null);
    setPanelOpen(true);
  }

  function openEdit(task: Task) {
    setEditing(task);
    setForm({
      title: task.title,
      description: task.description ?? "",
      project_id: task.project_id ? String(task.project_id) : "",
      status: task.status,
      priority: task.priority,
      due_date: task.due_date ?? "",
    });
    setFormError(null);
    setPanelOpen(true);
  }

  async function handleSubmit() {
    if (!form.title.trim()) {
      setFormError("Give the task a title.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      title: form.title.trim(),
      description: form.description.trim() || null,
      project_id: form.project_id ? Number(form.project_id) : null,
      status: form.status,
      priority: form.priority,
      due_date: form.due_date || null,
    };
    try {
      if (editing) {
        const res = await api.put<Task>(`/tasks/${editing.id}`, payload);
        setTasks((prev) => prev.map((t) => (t.id === editing.id ? res.data : t)));
      } else {
        const res = await api.post<Task>("/tasks", payload);
        setTasks((prev) => [res.data, ...prev]);
      }
      setPanelOpen(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the task.");
    } finally {
      setSaving(false);
    }
  }

  async function cycleStatus(task: Task) {
    const order: Task["status"][] = ["todo", "in_progress", "done"];
    const next = order[(order.indexOf(task.status) + 1) % order.length];
    setTasks((prev) => prev.map((t) => (t.id === task.id ? { ...t, status: next } : t)));
    try {
      const res = await api.put<Task>(`/tasks/${task.id}`, {
        title: task.title,
        description: task.description,
        project_id: task.project_id,
        priority: task.priority,
        due_date: task.due_date,
        status: next,
      });
      setTasks((prev) => prev.map((t) => (t.id === task.id ? res.data : t)));
    } catch {
      setTasks((prev) => prev.map((t) => (t.id === task.id ? task : t)));
    }
  }

  async function handleDelete(id: number) {
    try {
      await api.delete(`/tasks/${id}`);
      setTasks((prev) => prev.filter((t) => t.id !== id));
    } finally {
      setConfirmId(null);
    }
  }

  const visible = useMemo(() => {
    const priorityRank: Record<string, number> = { high: 0, medium: 1, low: 2 };
    return tasks
      .filter((t) => (statusFilter === "all" ? true : t.status === statusFilter))
      .filter((t) => (priorityFilter === "all" ? true : t.priority === priorityFilter))
      .filter((t) =>
        projectFilter === "all"
          ? true
          : projectFilter === "none"
            ? t.project_id === null
            : String(t.project_id) === projectFilter,
      )
      .filter((t) => t.title.toLowerCase().includes(search.toLowerCase()))
      .sort((a, b) => {
        if (sortBy === "due") {
          if (!a.due_date) return 1;
          if (!b.due_date) return -1;
          return a.due_date.localeCompare(b.due_date);
        }
        if (sortBy === "priority") return priorityRank[a.priority] - priorityRank[b.priority];
        return b.created_at.localeCompare(a.created_at);
      });
  }, [tasks, statusFilter, priorityFilter, projectFilter, search, sortBy]);

  return (
    <div>
      <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
        <p className="text-[0.875rem] text-muted">Everything you need to do, across all of your projects.</p>
        <Button onClick={openCreate}>
          <Plus className="h-4 w-4" strokeWidth={2} /> New task
        </Button>
      </div>

      <Card className="mb-4" padding={false}>
        <div className="flex flex-wrap items-center gap-2 border-b border-border p-3">
          <div className="flex min-w-[180px] flex-1 items-center gap-2 rounded-lg border border-border bg-surface px-3 py-1.5">
            <Search className="h-4 w-4 text-muted" strokeWidth={1.75} />
            <input
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search tasks"
              aria-label="Search tasks"
              className="w-full bg-transparent text-[0.8125rem] text-ink placeholder:text-muted/70 focus:outline-none"
            />
          </div>
          <select
            aria-label="Filter by status"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="all">All statuses</option>
            <option value="todo">To do</option>
            <option value="in_progress">In progress</option>
            <option value="done">Done</option>
          </select>
          <select
            aria-label="Filter by priority"
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="all">All priorities</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
          <select
            aria-label="Filter by project"
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="all">All projects</option>
            <option value="none">No project</option>
            {projects.map((p) => (
              <option key={p.id} value={String(p.id)}>
                {p.name}
              </option>
            ))}
          </select>
          <select
            aria-label="Sort tasks"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as typeof sortBy)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="created">Newest first</option>
            <option value="due">By due date</option>
            <option value="priority">By priority</option>
          </select>
        </div>

        {loading ? (
          <div className="p-5">
            <LoadingBlock label="Loading tasks" />
          </div>
        ) : error ? (
          <div className="p-5">
            <ErrorBlock message={error} onRetry={load} />
          </div>
        ) : visible.length === 0 ? (
          <div className="p-5">
            <EmptyState
              title={tasks.length === 0 ? "No tasks yet" : "Nothing matches these filters"}
              description={
                tasks.length === 0
                  ? "Add your first task and it will appear here with its status, priority and due date."
                  : "Try clearing the filters or searching for something else."
              }
              action={tasks.length === 0 ? <Button onClick={openCreate}>Add a task</Button> : undefined}
            />
          </div>
        ) : (
          <>
            {/* Desktop table */}
            <div className="hidden overflow-x-auto md:block">
              <table className="w-full text-left text-[0.875rem]">
                <thead className="sticky top-0 bg-surfaceMuted/70 text-[0.75rem] uppercase tracking-wide text-muted">
                  <tr>
                    <th className="px-4 py-2.5 font-medium">Task</th>
                    <th className="px-4 py-2.5 font-medium">Project</th>
                    <th className="px-4 py-2.5 font-medium">Priority</th>
                    <th className="px-4 py-2.5 font-medium">Due</th>
                    <th className="px-4 py-2.5 font-medium">Status</th>
                    <th className="px-4 py-2.5 text-right font-medium">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {visible.map((task) => {
                    const overdue =
                      task.due_date && task.status !== "done" && isBefore(new Date(task.due_date), startOfDay(new Date()));
                    return (
                      <tr key={task.id} className="transition-colors hover:bg-surfaceMuted/40">
                        <td className="max-w-[280px] px-4 py-3">
                          <p className={`truncate font-medium ${task.status === "done" ? "text-muted line-through" : "text-ink"}`}>
                            {task.title}
                          </p>
                          {task.description && <p className="truncate text-[0.75rem] text-muted">{task.description}</p>}
                        </td>
                        <td className="px-4 py-3 text-muted">{projectName(task.project_id)}</td>
                        <td className="px-4 py-3">
                          <Badge tone={priorityTone(task.priority)}>{labelize(task.priority)}</Badge>
                        </td>
                        <td className="px-4 py-3">
                          {task.due_date ? (
                            <span className={overdue ? "text-danger" : "text-muted"}>
                              {format(new Date(`${task.due_date}T00:00:00`), "d MMM yyyy")}
                            </span>
                          ) : (
                            <span className="text-muted">—</span>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          <button type="button" onClick={() => cycleStatus(task)} title="Click to advance status">
                            <Badge tone={statusTone(task.status)}>{labelize(task.status)}</Badge>
                          </button>
                        </td>
                        <td className="px-4 py-3">
                          <div className="flex items-center justify-end gap-1">
                            <button
                              type="button"
                              onClick={() => openEdit(task)}
                              aria-label={`Edit ${task.title}`}
                              className="rounded-lg p-1.5 text-muted hover:bg-surfaceMuted hover:text-ink"
                            >
                              <Pencil className="h-4 w-4" strokeWidth={1.75} />
                            </button>
                            <button
                              type="button"
                              onClick={() => setConfirmId(task.id)}
                              aria-label={`Delete ${task.title}`}
                              className="rounded-lg p-1.5 text-muted hover:bg-danger/10 hover:text-danger"
                            >
                              <Trash2 className="h-4 w-4" strokeWidth={1.75} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Mobile cards */}
            <ul className="divide-y divide-border md:hidden">
              {visible.map((task) => (
                <li key={task.id} className="p-4">
                  <div className="flex items-start justify-between gap-2">
                    <p className={`text-[0.9375rem] font-medium ${task.status === "done" ? "text-muted line-through" : "text-ink"}`}>
                      {task.title}
                    </p>
                    <Badge tone={statusTone(task.status)}>{labelize(task.status)}</Badge>
                  </div>
                  <div className="mt-2 flex flex-wrap items-center gap-2 text-[0.75rem] text-muted">
                    <Badge tone={priorityTone(task.priority)}>{labelize(task.priority)}</Badge>
                    <span>{projectName(task.project_id)}</span>
                    {task.due_date && <span>· due {format(new Date(`${task.due_date}T00:00:00`), "d MMM")}</span>}
                  </div>
                  <div className="mt-3 flex gap-2">
                    <Button variant="secondary" size="sm" onClick={() => cycleStatus(task)}>
                      Advance status
                    </Button>
                    <Button variant="ghost" size="sm" onClick={() => openEdit(task)}>
                      Edit
                    </Button>
                    <Button variant="ghost" size="sm" className="text-danger" onClick={() => setConfirmId(task.id)}>
                      Delete
                    </Button>
                  </div>
                </li>
              ))}
            </ul>
          </>
        )}
      </Card>

      <Modal
        open={panelOpen}
        onClose={() => setPanelOpen(false)}
        title={editing ? "Edit task" : "New task"}
        subtitle="Tasks belong to a project, or stand alone."
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setPanelOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} loading={saving}>
              {editing ? "Save changes" : "Create task"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Title">
          <input
            className={inputClass}
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            placeholder="e.g. Review the monthly budget"
          />
        </Field>
        <Field label="Description" hint="Optional details for this task.">
          <textarea
            className={`${inputClass} min-h-[80px] resize-y`}
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
            placeholder="Anything worth remembering"
          />
        </Field>
        <Field label="Project">
          <select
            className={inputClass}
            value={form.project_id}
            onChange={(e) => setForm({ ...form, project_id: e.target.value })}
          >
            <option value="">No project</option>
            {projects.map((p) => (
              <option key={p.id} value={String(p.id)}>
                {p.name}
              </option>
            ))}
          </select>
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Priority">
            <select
              className={inputClass}
              value={form.priority}
              onChange={(e) => setForm({ ...form, priority: e.target.value as Task["priority"] })}
            >
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
          </Field>
          <Field label="Status">
            <select
              className={inputClass}
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value as Task["status"] })}
            >
              <option value="todo">To do</option>
              <option value="in_progress">In progress</option>
              <option value="done">Done</option>
            </select>
          </Field>
        </div>
        <Field label="Due date" hint="Leave empty if there is no deadline.">
          <input
            type="date"
            className={inputClass}
            value={form.due_date}
            onChange={(e) => setForm({ ...form, due_date: e.target.value })}
          />
        </Field>
      </Modal>

      <Modal
        open={confirmId !== null}
        onClose={() => setConfirmId(null)}
        title="Delete task"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirmId(null)}>
              Keep it
            </Button>
            <Button variant="danger" onClick={() => confirmId !== null && handleDelete(confirmId)}>
              Delete task
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">This task will be permanently removed. This cannot be undone.</p>
      </Modal>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { format } from "date-fns";
import { Plus, Pencil, Trash2 } from "lucide-react";
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Cell,
} from "recharts";
import { api } from "../lib/api";
import type { Account, Budget, FinanceSummary, Transaction } from "../types";
import Card, { CardHeader } from "../components/ui/Card";
import StatCard from "../components/ui/StatCard";
import Badge from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

const CATEGORY_COLORS = ["#4338CA", "#0D9488", "#16A34A", "#D97706", "#DC2626", "#6B7280", "#7C3AED", "#0891B2"];

function currency(n: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 2 }).format(n);
}

type TxForm = {
  account_id: string;
  category: string;
  amount: string;
  type: Transaction["type"];
  date: string;
  note: string;
};

type AccountForm = { name: string; type: Account["type"]; balance: string };
type BudgetForm = { category: string; monthly_limit: string };

const todayISO = format(new Date(), "yyyy-MM-dd");

export default function FinancePage() {
  const [summary, setSummary] = useState<FinanceSummary | null>(null);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [txPanel, setTxPanel] = useState(false);
  const [editingTx, setEditingTx] = useState<Transaction | null>(null);
  const [txForm, setTxForm] = useState<TxForm>({
    account_id: "",
    category: "General",
    amount: "",
    type: "expense",
    date: todayISO,
    note: "",
  });

  const [accPanel, setAccPanel] = useState(false);
  const [editingAcc, setEditingAcc] = useState<Account | null>(null);
  const [accForm, setAccForm] = useState<AccountForm>({ name: "", type: "checking", balance: "0" });

  const [budgetPanel, setBudgetPanel] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [budgetForm, setBudgetForm] = useState<BudgetForm>({ category: "", monthly_limit: "" });

  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [confirm, setConfirm] = useState<{ kind: "tx" | "acc" | "budget"; id: number } | null>(null);

  const [typeFilter, setTypeFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [accountFilter, setAccountFilter] = useState("all");

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [s, a, t, b] = await Promise.all([
        api.get<FinanceSummary>("/finance/summary"),
        api.get<Account[]>("/finance/accounts"),
        api.get<Transaction[]>("/finance/transactions"),
        api.get<Budget[]>("/finance/budgets").catch(() => ({ data: [] as Budget[] })),
      ]);
      setSummary(s.data);
      setAccounts(a.data);
      setTransactions(t.data);
      setBudgets(b.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your finances.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  function openTxCreate() {
    setEditingTx(null);
    setTxForm({
      account_id: accounts[0] ? String(accounts[0].id) : "",
      category: "General",
      amount: "",
      type: "expense",
      date: todayISO,
      note: "",
    });
    setFormError(null);
    setTxPanel(true);
  }

  function openTxEdit(t: Transaction) {
    setEditingTx(t);
    setTxForm({
      account_id: String(t.account_id),
      category: t.category,
      amount: String(t.amount),
      type: t.type,
      date: t.date,
      note: t.note ?? "",
    });
    setFormError(null);
    setTxPanel(true);
  }

  async function saveTx() {
    if (!txForm.account_id) {
      setFormError("Create an account first, then record transactions against it.");
      return;
    }
    const amount = Number(txForm.amount);
    if (!amount || amount <= 0) {
      setFormError("Enter an amount greater than zero.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      account_id: Number(txForm.account_id),
      category: txForm.category.trim() || "General",
      amount,
      type: txForm.type,
      date: txForm.date,
      note: txForm.note.trim() || null,
    };
    try {
      if (editingTx) {
        const res = await api.put<Transaction>(`/finance/transactions/${editingTx.id}`, payload);
        setTransactions((prev) => prev.map((t) => (t.id === editingTx.id ? res.data : t)));
      } else {
        const res = await api.post<Transaction>("/finance/transactions", payload);
        setTransactions((prev) => [res.data, ...prev]);
      }
      setTxPanel(false);
      const s = await api.get<FinanceSummary>("/finance/summary");
      setSummary(s.data);
      const a = await api.get<Account[]>("/finance/accounts");
      setAccounts(a.data);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the transaction.");
    } finally {
      setSaving(false);
    }
  }

  function openAccCreate() {
    setEditingAcc(null);
    setAccForm({ name: "", type: "checking", balance: "0" });
    setFormError(null);
    setAccPanel(true);
  }

  function openAccEdit(a: Account) {
    setEditingAcc(a);
    setAccForm({ name: a.name, type: a.type, balance: String(a.balance) });
    setFormError(null);
    setAccPanel(true);
  }

  async function saveAcc() {
    if (!accForm.name.trim()) {
      setFormError("Give the account a name.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      name: accForm.name.trim(),
      type: accForm.type,
      balance: Number(accForm.balance) || 0,
    };
    try {
      if (editingAcc) {
        const res = await api.put<Account>(`/finance/accounts/${editingAcc.id}`, payload);
        setAccounts((prev) => prev.map((a) => (a.id === editingAcc.id ? res.data : a)));
      } else {
        const res = await api.post<Account>("/finance/accounts", payload);
        setAccounts((prev) => [...prev, res.data]);
      }
      setAccPanel(false);
      const s = await api.get<FinanceSummary>("/finance/summary");
      setSummary(s.data);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the account.");
    } finally {
      setSaving(false);
    }
  }

  function openBudgetCreate() {
    setEditingBudget(null);
    setBudgetForm({ category: "", monthly_limit: "" });
    setFormError(null);
    setBudgetPanel(true);
  }

  function openBudgetEdit(b: Budget) {
    setEditingBudget(b);
    setBudgetForm({ category: b.category, monthly_limit: String(b.monthly_limit) });
    setFormError(null);
    setBudgetPanel(true);
  }

  async function saveBudget() {
    if (!budgetForm.category.trim() || !Number(budgetForm.monthly_limit)) {
      setFormError("Enter a category and a monthly limit.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = { category: budgetForm.category.trim(), monthly_limit: Number(budgetForm.monthly_limit) };
    try {
      if (editingBudget) {
        const res = await api.put<Budget>(`/finance/budgets/${editingBudget.id}`, payload);
        setBudgets((prev) => prev.map((b) => (b.id === editingBudget.id ? res.data : b)));
      } else {
        const res = await api.post<Budget>("/finance/budgets", payload);
        setBudgets((prev) => [...prev, res.data]);
      }
      setBudgetPanel(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the budget.");
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete() {
    if (!confirm) return;
    const { kind, id } = confirm;
    try {
      if (kind === "tx") {
        await api.delete(`/finance/transactions/${id}`);
        setTransactions((prev) => prev.filter((t) => t.id !== id));
      } else if (kind === "acc") {
        await api.delete(`/finance/accounts/${id}`);
        setAccounts((prev) => prev.filter((a) => a.id !== id));
      } else {
        await api.delete(`/finance/budgets/${id}`);
        setBudgets((prev) => prev.filter((b) => b.id !== id));
      }
    } finally {
      setConfirm(null);
    }
  }

  const categoryData = useMemo(
    () =>
      (summary?.by_category ?? []).map((c, i) => ({
        ...c,
        fill: CATEGORY_COLORS[i % CATEGORY_COLORS.length],
      })),
    [summary],
  );

  const visibleTx = useMemo(
    () =>
      transactions
        .filter((t) => (typeFilter === "all" ? true : t.type === typeFilter))
        .filter((t) => (categoryFilter === "all" ? true : t.category === categoryFilter))
        .filter((t) => (accountFilter === "all" ? true : String(t.account_id) === accountFilter))
        .sort((a, b) => b.date.localeCompare(a.date)),
    [transactions, typeFilter, categoryFilter, accountFilter],
  );

  const spendByCategory = useMemo(() => {
    const month = format(new Date(), "yyyy-MM");
    const map = new Map<string, number>();
    for (const t of transactions) {
      if (t.type !== "expense" || !t.date.startsWith(month)) continue;
      map.set(t.category, (map.get(t.category) ?? 0) + t.amount);
    }
    return map;
  }, [transactions]);

  if (loading) {
    return (
      <div className="grid gap-4 md:grid-cols-4">
        {[0, 1, 2, 3].map((i) => (
          <Card key={i}>
            <LoadingBlock />
          </Card>
        ))}
      </div>
    );
  }
  if (error) return <ErrorBlock message={error} onRetry={load} />;

  return (
    <div className="space-y-5">
      <div className="grid gap-4 md:grid-cols-4">
        <StatCard label="Total balance" value={currency(summary?.total_balance ?? 0)} hint="across all accounts" />
        <StatCard label="Income this month" value={currency(summary?.month_income ?? 0)} trend={{ value: "income", positive: true }} />
        <StatCard label="Expenses this month" value={currency(summary?.month_expense ?? 0)} trend={{ value: "spending", positive: false }} />
        <StatCard
          label="Net this month"
          value={currency((summary?.month_income ?? 0) - (summary?.month_expense ?? 0))}
          hint="income − expenses"
        />
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHeader title="Spending by category" subtitle="Expense totals recorded in your transactions" />
          {categoryData.length === 0 ? (
            <EmptyState title="No category data" description="Record an expense and the breakdown appears here." />
          ) : (
            <div className="h-56">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={categoryData} margin={{ top: 4, right: 4, bottom: 0, left: -18 }}>
                  <CartesianGrid stroke="var(--border)" vertical={false} />
                  <XAxis dataKey="category" tick={{ fontSize: 11, fill: "var(--muted)" }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11, fill: "var(--muted)" }} axisLine={false} tickLine={false} />
                  <Tooltip
                    cursor={{ fill: "var(--surface-muted)" }}
                    contentStyle={{
                      borderRadius: 12,
                      border: "1px solid var(--border)",
                      fontSize: 12,
                      boxShadow: "0 4px 12px rgba(16,24,40,0.08)",
                    }}
                    formatter={(v: number) => [currency(v), "Total"]}
                  />
                  <Bar dataKey="total" radius={[6, 6, 0, 0]}>
                    {categoryData.map((entry) => (
                      <Cell key={entry.category} fill={entry.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </Card>

        <Card>
          <CardHeader
            title="Accounts"
            action={
              <Button variant="ghost" size="sm" onClick={openAccCreate}>
                <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Add
              </Button>
            }
          />
          {accounts.length === 0 ? (
            <EmptyState title="No accounts" description="Add a bank, cash or card account to start tracking." />
          ) : (
            <ul className="divide-y divide-border">
              {accounts.map((a) => (
                <li key={a.id} className="flex items-center justify-between gap-2 py-2.5">
                  <div className="min-w-0">
                    <p className="truncate text-[0.875rem] font-medium text-ink">{a.name}</p>
                    <p className="text-[0.75rem] capitalize text-muted">{a.type}</p>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="mr-1 font-display text-[0.875rem] font-semibold text-ink">{currency(a.balance)}</span>
                    <button
                      type="button"
                      onClick={() => openAccEdit(a)}
                      aria-label={`Edit ${a.name}`}
                      className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                    >
                      <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                    </button>
                    <button
                      type="button"
                      onClick={() => setConfirm({ kind: "acc", id: a.id })}
                      aria-label={`Delete ${a.name}`}
                      className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                    >
                      <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <Card padding={false}>
        <div className="flex flex-wrap items-center gap-2 border-b border-border p-3">
          <h3 className="mr-auto font-display text-[1.0625rem] font-semibold text-ink">Transactions</h3>
          <select
            aria-label="Filter by type"
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="all">All types</option>
            <option value="income">Income</option>
            <option value="expense">Expense</option>
          </select>
          <select
            aria-label="Filter by category"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="all">All categories</option>
            {Array.from(new Set(transactions.map((t) => t.category))).map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
          <select
            aria-label="Filter by account"
            value={accountFilter}
            onChange={(e) => setAccountFilter(e.target.value)}
            className="rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink focus:border-primary focus:outline-none"
          >
            <option value="all">All accounts</option>
            {accounts.map((a) => (
              <option key={a.id} value={String(a.id)}>
                {a.name}
              </option>
            ))}
          </select>
          <Button size="sm" onClick={openTxCreate}>
            <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Add transaction
          </Button>
        </div>

        {visibleTx.length === 0 ? (
          <div className="p-5">
            <EmptyState
              title={transactions.length === 0 ? "No transactions yet" : "Nothing matches these filters"}
              description={
                transactions.length === 0
                  ? "Record income and expenses to see balances, categories and trends."
                  : "Clear the filters to see everything again."
              }
              action={transactions.length === 0 ? <Button onClick={openTxCreate}>Record a transaction</Button> : undefined}
            />
          </div>
        ) : (
          <>
            <div className="hidden overflow-x-auto md:block">
              <table className="w-full text-left text-[0.875rem]">
                <thead className="sticky top-0 bg-surfaceMuted/70 text-[0.75rem] uppercase tracking-wide text-muted">
                  <tr>
                    <th className="px-4 py-2.5 font-medium">Date</th>
                    <th className="px-4 py-2.5 font-medium">Category</th>
                    <th className="px-4 py-2.5 font-medium">Account</th>
                    <th className="px-4 py-2.5 font-medium">Note</th>
                    <th className="px-4 py-2.5 font-medium">Type</th>
                    <th className="px-4 py-2.5 text-right font-medium">Amount</th>
                    <th className="px-4 py-2.5 text-right font-medium">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {visibleTx.map((t) => (
                    <tr key={t.id} className="hover:bg-surfaceMuted/40">
                      <td className="whitespace-nowrap px-4 py-3 text-muted">
                        {format(new Date(`${t.date}T00:00:00`), "d MMM yyyy")}
                      </td>
                      <td className="px-4 py-3 font-medium text-ink">{t.category}</td>
                      <td className="px-4 py-3 text-muted">{accounts.find((a) => a.id === t.account_id)?.name ?? "—"}</td>
                      <td className="max-w-[220px] truncate px-4 py-3 text-muted">{t.note || "—"}</td>
                      <td className="px-4 py-3">
                        <Badge tone={t.type === "income" ? "success" : "danger"}>
                          {t.type === "income" ? "Income" : "Expense"}
                        </Badge>
                      </td>
                      <td
                        className={`whitespace-nowrap px-4 py-3 text-right font-medium ${
                          t.type === "income" ? "text-success" : "text-ink"
                        }`}
                      >
                        {t.type === "income" ? "+" : "−"}
                        {currency(t.amount)}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            type="button"
                            onClick={() => openTxEdit(t)}
                            aria-label="Edit transaction"
                            className="rounded-lg p-1.5 text-muted hover:bg-surfaceMuted hover:text-ink"
                          >
                            <Pencil className="h-4 w-4" strokeWidth={1.75} />
                          </button>
                          <button
                            type="button"
                            onClick={() => setConfirm({ kind: "tx", id: t.id })}
                            aria-label="Delete transaction"
                            className="rounded-lg p-1.5 text-muted hover:bg-danger/10 hover:text-danger"
                          >
                            <Trash2 className="h-4 w-4" strokeWidth={1.75} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <ul className="divide-y divide-border md:hidden">
              {visibleTx.map((t) => (
                <li key={t.id} className="flex items-start justify-between gap-3 p-4">
                  <div className="min-w-0">
                    <p className="truncate text-[0.9375rem] font-medium text-ink">{t.category}</p>
                    <p className="text-[0.75rem] text-muted">
                      {format(new Date(`${t.date}T00:00:00`), "d MMM")} ·{" "}
                      {accounts.find((a) => a.id === t.account_id)?.name ?? "—"}
                    </p>
                    {t.note && <p className="mt-1 truncate text-[0.75rem] text-muted">{t.note}</p>}
                  </div>
                  <div className="flex shrink-0 flex-col items-end gap-1">
                    <span className={`font-medium ${t.type === "income" ? "text-success" : "text-ink"}`}>
                      {t.type === "income" ? "+" : "−"}
                      {currency(t.amount)}
                    </span>
                    <div className="flex gap-1">
                      <button
                        type="button"
                        onClick={() => openTxEdit(t)}
                        aria-label="Edit transaction"
                        className="rounded p-1 text-muted hover:bg-surfaceMuted"
                      >
                        <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                      <button
                        type="button"
                        onClick={() => setConfirm({ kind: "tx", id: t.id })}
                        aria-label="Delete transaction"
                        className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                      >
                        <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </>
        )}
      </Card>

      <Card>
        <CardHeader
          title="Monthly budgets"
          subtitle="Limit per category for the current month"
          action={
            <Button variant="ghost" size="sm" onClick={openBudgetCreate}>
              <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Add budget
            </Button>
          }
        />
        {budgets.length === 0 ? (
          <EmptyState title="No budgets set" description="Set a monthly limit per category to keep spending in view." />
        ) : (
          <ul className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {budgets.map((b) => {
              const spent = spendByCategory.get(b.category) ?? 0;
              const pct = b.monthly_limit > 0 ? Math.round((spent / b.monthly_limit) * 100) : 0;
              const tone = pct >= 100 ? "bg-danger" : pct >= 80 ? "bg-warning" : "bg-success";
              return (
                <li key={b.id} className="rounded-lg border border-border p-3">
                  <div className="flex items-center justify-between gap-2">
                    <p className="truncate text-[0.875rem] font-medium text-ink">{b.category}</p>
                    <div className="flex shrink-0 gap-1">
                      <button
                        type="button"
                        onClick={() => openBudgetEdit(b)}
                        aria-label={`Edit ${b.category} budget`}
                        className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                      >
                        <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                      <button
                        type="button"
                        onClick={() => setConfirm({ kind: "budget", id: b.id })}
                        aria-label={`Delete ${b.category} budget`}
                        className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                      >
                        <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                    </div>
                  </div>
                  <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-surfaceMuted">
                    <div className={`h-full rounded-full ${tone}`} style={{ width: `${Math.min(100, pct)}%` }} />
                  </div>
                  <p className="mt-1.5 text-[0.75rem] text-muted">
                    {currency(spent)} of {currency(b.monthly_limit)} · {pct}%
                  </p>
                </li>
              );
            })}
          </ul>
        )}
      </Card>

      {/* Transaction panel */}
      <Modal
        open={txPanel}
        onClose={() => setTxPanel(false)}
        title={editingTx ? "Edit transaction" : "New transaction"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setTxPanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveTx} loading={saving}>
              {editingTx ? "Save changes" : "Add transaction"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <div className="mb-4 flex gap-2">
          {(["expense", "income"] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTxForm({ ...txForm, type: t })}
              className={`flex-1 rounded-lg border px-3 py-2 text-[0.8125rem] font-medium capitalize transition-colors ${
                txForm.type === t
                  ? "border-primary bg-primary/10 text-primary"
                  : "border-border bg-surface text-muted hover:bg-surfaceMuted"
              }`}
            >
              {t}
            </button>
          ))}
        </div>
        <Field label="Account">
          <select
            className={inputClass}
            value={txForm.account_id}
            onChange={(e) => setTxForm({ ...txForm, account_id: e.target.value })}
          >
            <option value="">Select an account</option>
            {accounts.map((a) => (
              <option key={a.id} value={String(a.id)}>
                {a.name}
              </option>
            ))}
          </select>
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Amount">
            <input
              type="number"
              min="0"
              step="0.01"
              className={inputClass}
              value={txForm.amount}
              onChange={(e) => setTxForm({ ...txForm, amount: e.target.value })}
              placeholder="0.00"
            />
          </Field>
          <Field label="Date">
            <input
              type="date"
              className={inputClass}
              value={txForm.date}
              onChange={(e) => setTxForm({ ...txForm, date: e.target.value })}
            />
          </Field>
        </div>
        <Field label="Category">
          <input
            className={inputClass}
            value={txForm.category}
            onChange={(e) => setTxForm({ ...txForm, category: e.target.value })}
            placeholder="e.g. Groceries"
          />
        </Field>
        <Field label="Note" hint="Optional">
          <input
            className={inputClass}
            value={txForm.note}
            onChange={(e) => setTxForm({ ...txForm, note: e.target.value })}
            placeholder="What was this for?"
          />
        </Field>
      </Modal>

      {/* Account panel */}
      <Modal
        open={accPanel}
        onClose={() => setAccPanel(false)}
        title={editingAcc ? "Edit account" : "New account"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setAccPanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveAcc} loading={saving}>
              {editingAcc ? "Save changes" : "Add account"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Account name">
          <input
            className={inputClass}
            value={accForm.name}
            onChange={(e) => setAccForm({ ...accForm, name: e.target.value })}
            placeholder="e.g. Main checking"
          />
        </Field>
        <Field label="Type">
          <select
            className={inputClass}
            value={accForm.type}
            onChange={(e) => setAccForm({ ...accForm, type: e.target.value as Account["type"] })}
          >
            <option value="checking">Checking</option>
            <option value="savings">Savings</option>
            <option value="credit">Credit</option>
            <option value="cash">Cash</option>
            <option value="investment">Investment</option>
          </select>
        </Field>
        <Field label="Current balance">
          <input
            type="number"
            step="0.01"
            className={inputClass}
            value={accForm.balance}
            onChange={(e) => setAccForm({ ...accForm, balance: e.target.value })}
          />
        </Field>
      </Modal>

      {/* Budget panel */}
      <Modal
        open={budgetPanel}
        onClose={() => setBudgetPanel(false)}
        title={editingBudget ? "Edit budget" : "New budget"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setBudgetPanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveBudget} loading={saving}>
              {editingBudget ? "Save changes" : "Add budget"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Category">
          <input
            className={inputClass}
            value={budgetForm.category}
            onChange={(e) => setBudgetForm({ ...budgetForm, category: e.target.value })}
            placeholder="e.g. Groceries"
          />
        </Field>
        <Field label="Monthly limit">
          <input
            type="number"
            min="0"
            step="0.01"
            className={inputClass}
            value={budgetForm.monthly_limit}
            onChange={(e) => setBudgetForm({ ...budgetForm, monthly_limit: e.target.value })}
            placeholder="0.00"
          />
        </Field>
      </Modal>

      <Modal
        open={confirm !== null}
        onClose={() => setConfirm(null)}
        title="Confirm delete"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirm(null)}>
              Cancel
            </Button>
            <Button variant="danger" onClick={handleDelete}>
              Delete
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">
          {confirm?.kind === "acc"
            ? "Deleting an account also removes the transactions recorded against it."
            : "This item will be permanently removed. This cannot be undone."}
        </p>
      </Modal>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { format, subDays } from "date-fns";
import { Plus, Pencil, Trash2, Check } from "lucide-react";
import { api } from "../lib/api";
import type { Habit, HabitLog, HabitSummaryItem } from "../types";
import Card from "../components/ui/Card";
import StatCard from "../components/ui/StatCard";
import Badge, { labelize } from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

const COLORS = ["#0D9488", "#4338CA", "#16A34A", "#D97706", "#DC2626", "#7C3AED"];

interface FormState {
  name: string;
  frequency: Habit["frequency"];
  target_per_period: string;
  color: string;
}

const emptyForm: FormState = { name: "", frequency: "daily", target_per_period: "1", color: COLORS[0] };

export default function HabitsPage() {
  const [summary, setSummary] = useState<HabitSummaryItem[]>([]);
  const [habits, setHabits] = useState<Habit[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const [editing, setEditing] = useState<Habit | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [confirmId, setConfirmId] = useState<number | null>(null);

  // habit_id -> set of logged dates in the last 30 days
  const [loggedDates, setLoggedDates] = useState<Record<number, Set<string>>>({});
  const today = format(new Date(), "yyyy-MM-dd");

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [s, h] = await Promise.all([
        api.get<HabitSummaryItem[]>("/habits/summary"),
        api.get<Habit[]>("/habits"),
      ]);
      setSummary(s.data);
      setHabits(h.data);

      const entries = await Promise.all(
        h.data.map(async (habit) => {
          try {
            const res = await api.get<HabitLog[]>(`/habits/${habit.id}/logs`);
            const set = new Set(res.data.filter((l) => l.completed).map((l) => l.date));
            return [habit.id, set] as [number, Set<string>];
          } catch {
            return [habit.id, new Set<string>()] as [number, Set<string>];
          }
        }),
      );
      setLoggedDates(Object.fromEntries(entries));
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your habits.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setFormError(null);
    setPanelOpen(true);
  }

  function openEdit(habit: Habit) {
    setEditing(habit);
    setForm({
      name: habit.name,
      frequency: habit.frequency,
      target_per_period: String(habit.target_per_period),
      color: habit.color || COLORS[0],
    });
    setFormError(null);
    setPanelOpen(true);
  }

  async function handleSubmit() {
    if (!form.name.trim()) {
      setFormError("Give the habit a name.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      name: form.name.trim(),
      frequency: form.frequency,
      target_per_period: Number(form.target_per_period) || 1,
      color: form.color,
    };
    try {
      if (editing) {
        await api.put(`/habits/${editing.id}`, payload);
      } else {
        await api.post("/habits", payload);
      }
      setPanelOpen(false);
      await load();
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the habit.");
    } finally {
      setSaving(false);
    }
  }

  async function markToday(habit: Habit) {
    try {
      await api.post(`/habits/${habit.id}/log`, { date: today, completed: true });
      await load();
    } catch {
      /* keep the previous state */
    }
  }

  async function handleDelete(id: number) {
    try {
      await api.delete(`/habits/${id}`);
      setConfirmId(null);
      await load();
    } catch {
      setConfirmId(null);
    }
  }

  const last30 = useMemo(() => Array.from({ length: 30 }, (_, i) => format(subDays(new Date(), 29 - i), "yyyy-MM-dd")), []);

  const summaryById = useMemo(() => {
    const map = new Map<number, HabitSummaryItem>();
    for (const s of summary) map.set(s.habit_id, s);
    return map;
  }, [summary]);

  const avgCompletion = summary.length
    ? Math.round(summary.reduce((acc, s) => acc + s.completion_rate, 0) / summary.length)
    : 0;
  const bestStreak = summary.length ? Math.max(...summary.map((s) => s.streak)) : 0;
  const doneToday = habits.filter((h) => loggedDates[h.id]?.has(today)).length;

  if (loading) {
    return (
      <div className="grid gap-4 md:grid-cols-3">
        {[0, 1, 2].map((i) => (
          <Card key={i}>
            <LoadingBlock />
          </Card>
        ))}
      </div>
    );
  }
  if (error) return <ErrorBlock message={error} onRetry={load} />;

  return (
    <div className="space-y-5">
      <div className="grid gap-4 md:grid-cols-4">
        <StatCard label="Habits tracked" value={habits.length} hint="active routines" />
        <StatCard label="Done today" value={`${doneToday}/${habits.length || 0}`} hint="marked complete" />
        <StatCard label="Average completion" value={`${avgCompletion}%`} hint="last 30 days" />
        <StatCard label="Best streak" value={`${bestStreak} d`} hint="current run" />
      </div>

      <div className="flex items-center justify-between gap-3">
        <p className="text-[0.875rem] text-muted">Tick a habit off as you do it — the streaks do the rest.</p>
        <Button onClick={openCreate}>
          <Plus className="h-4 w-4" strokeWidth={2} /> New habit
        </Button>
      </div>

      {habits.length === 0 ? (
        <EmptyState
          title="No habits yet"
          description="Add the routines you want to keep — reading, walking, stretching — and tick them off each day."
          action={<Button onClick={openCreate}>Add your first habit</Button>}
        />
      ) : (
        <div className="grid gap-4 lg:grid-cols-2">
          {habits.map((habit) => {
            const stat = summaryById.get(habit.id);
            const dates = loggedDates[habit.id] ?? new Set<string>();
            const isDoneToday = dates.has(today);
            return (
              <Card key={habit.id}>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex min-w-0 items-center gap-2">
                    <span
                      className="h-2.5 w-2.5 shrink-0 rounded-full"
                      style={{ backgroundColor: habit.color }}
                      aria-hidden="true"
                    />
                    <div className="min-w-0">
                      <h3 className="truncate font-display text-[1.0625rem] font-semibold text-ink">{habit.name}</h3>
                      <p className="text-[0.75rem] text-muted">
                        {labelize(habit.frequency)} · target {habit.target_per_period}
                      </p>
                    </div>
                  </div>
                  <div className="flex shrink-0 items-center gap-1">
                    <button
                      type="button"
                      onClick={() => openEdit(habit)}
                      aria-label={`Edit ${habit.name}`}
                      className="rounded-lg p-1.5 text-muted hover:bg-surfaceMuted hover:text-ink"
                    >
                      <Pencil className="h-4 w-4" strokeWidth={1.75} />
                    </button>
                    <button
                      type="button"
                      onClick={() => setConfirmId(habit.id)}
                      aria-label={`Delete ${habit.name}`}
                      className="rounded-lg p-1.5 text-muted hover:bg-danger/10 hover:text-danger"
                    >
                      <Trash2 className="h-4 w-4" strokeWidth={1.75} />
                    </button>
                  </div>
                </div>

                <div className="mt-4 flex items-end gap-4">
                  <div>
                    <p className="font-display text-[1.5rem] font-semibold leading-none text-ink">
                      {stat?.streak ?? 0}
                    </p>
                    <p className="text-[0.75rem] text-muted">day streak</p>
                  </div>
                  <div>
                    <p className="font-display text-[1.5rem] font-semibold leading-none text-ink">
                      {Math.round(stat?.completion_rate ?? 0)}%
                    </p>
                    <p className="text-[0.75rem] text-muted">completion</p>
                  </div>
                  <div className="ml-auto">
                    <Button
                      size="sm"
                      variant={isDoneToday ? "secondary" : "primary"}
                      onClick={() => markToday(habit)}
                      disabled={isDoneToday}
                    >
                      <Check className="h-3.5 w-3.5" strokeWidth={2.5} />
                      {isDoneToday ? "Done today" : "Mark today"}
                    </Button>
                  </div>
                </div>

                <div className="mt-4">
                  <p className="mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">
                    Last 30 days
                  </p>
                  <div className="flex gap-[3px]">
                    {last30.map((d) => {
                      const on = dates.has(d);
                      return (
                        <span
                          key={d}
                          title={d}
                          className="h-6 flex-1 rounded-[3px]"
                          style={{ backgroundColor: on ? habit.color : "var(--surface-muted)" }}
                        />
                      );
                    })}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      <Modal
        open={panelOpen}
        onClose={() => setPanelOpen(false)}
        title={editing ? "Edit habit" : "New habit"}
        subtitle="Small routines, tracked honestly."
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setPanelOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} loading={saving}>
              {editing ? "Save changes" : "Create habit"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Habit name">
          <input
            className={inputClass}
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            placeholder="e.g. Read 20 pages"
          />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Frequency">
            <select
              className={inputClass}
              value={form.frequency}
              onChange={(e) => setForm({ ...form, frequency: e.target.value as Habit["frequency"] })}
            >
              <option value="daily">Daily</option>
              <option value="weekly">Weekly</option>
            </select>
          </Field>
          <Field label="Target per period">
            <input
              type="number"
              min="1"
              className={inputClass}
              value={form.target_per_period}
              onChange={(e) => setForm({ ...form, target_per_period: e.target.value })}
            />
          </Field>
        </div>
        <Field label="Colour">
          <div className="flex flex-wrap gap-2">
            {COLORS.map((c) => (
              <button
                key={c}
                type="button"
                aria-label={`Use colour ${c}`}
                aria-pressed={form.color === c}
                onClick={() => setForm({ ...form, color: c })}
                className={`h-7 w-7 rounded-full border-2 ${form.color === c ? "border-ink" : "border-transparent"}`}
                style={{ backgroundColor: c }}
              />
            ))}
          </div>
        </Field>
      </Modal>

      <Modal
        open={confirmId !== null}
        onClose={() => setConfirmId(null)}
        title="Delete habit"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirmId(null)}>
              Keep it
            </Button>
            <Button variant="danger" onClick={() => confirmId !== null && handleDelete(confirmId)}>
              Delete habit
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">This habit and its entire log history will be removed.</p>
      </Modal>

      <div className="flex flex-wrap items-center gap-2">
        <Badge tone="accent">Streaks and rates are calculated from your own logs</Badge>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { format } from "date-fns";
import { Plus, Pencil, Trash2 } from "lucide-react";
import { api } from "../lib/api";
import type { CareerMilestone, Course, Skill } from "../types";
import Card, { CardHeader } from "../components/ui/Card";
import Badge, { labelize, statusTone } from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

type SkillForm = { name: string; category: string; level: string };
type CourseForm = { title: string; provider: string; status: Course["status"]; progress: string; target_date: string };
type MilestoneForm = { title: string; description: string; date: string };

const todayISO = format(new Date(), "yyyy-MM-dd");

export default function LearningPage() {
  const [skills, setSkills] = useState<Skill[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [milestones, setMilestones] = useState<CareerMilestone[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  const [skillPanel, setSkillPanel] = useState(false);
  const [editingSkill, setEditingSkill] = useState<Skill | null>(null);
  const [skillForm, setSkillForm] = useState<SkillForm>({ name: "", category: "", level: "1" });

  const [coursePanel, setCoursePanel] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [courseForm, setCourseForm] = useState<CourseForm>({
    title: "",
    provider: "",
    status: "in_progress",
    progress: "0",
    target_date: "",
  });

  const [milestonePanel, setMilestonePanel] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<CareerMilestone | null>(null);
  const [milestoneForm, setMilestoneForm] = useState<MilestoneForm>({ title: "", description: "", date: todayISO });

  const [confirm, setConfirm] = useState<{ kind: "skill" | "course" | "milestone"; id: number } | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [s, c, m] = await Promise.all([
        api.get<Skill[]>("/learning/skills"),
        api.get<Course[]>("/learning/courses"),
        api.get<CareerMilestone[]>("/learning/career-milestones"),
      ]);
      setSkills(s.data);
      setCourses(c.data);
      setMilestones(m.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your learning record.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function saveSkill() {
    if (!skillForm.name.trim()) {
      setFormError("Name the skill.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      name: skillForm.name.trim(),
      category: skillForm.category.trim() || null,
      level: Math.min(5, Math.max(1, Number(skillForm.level) || 1)),
    };
    try {
      if (editingSkill) {
        const res = await api.put<Skill>(`/learning/skills/${editingSkill.id}`, payload);
        setSkills((prev) => prev.map((s) => (s.id === editingSkill.id ? res.data : s)));
      } else {
        const res = await api.post<Skill>("/learning/skills", payload);
        setSkills((prev) => [...prev, res.data]);
      }
      setSkillPanel(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the skill.");
    } finally {
      setSaving(false);
    }
  }

  async function saveCourse() {
    if (!courseForm.title.trim()) {
      setFormError("Give the course a title.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      title: courseForm.title.trim(),
      provider: courseForm.provider.trim() || null,
      status: courseForm.status,
      progress: Math.min(100, Math.max(0, Number(courseForm.progress) || 0)),
      target_date: courseForm.target_date || null,
    };
    try {
      if (editingCourse) {
        const res = await api.put<Course>(`/learning/courses/${editingCourse.id}`, payload);
        setCourses((prev) => prev.map((c) => (c.id === editingCourse.id ? res.data : c)));
      } else {
        const res = await api.post<Course>("/learning/courses", payload);
        setCourses((prev) => [res.data, ...prev]);
      }
      setCoursePanel(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the course.");
    } finally {
      setSaving(false);
    }
  }

  async function saveMilestone() {
    if (!milestoneForm.title.trim()) {
      setFormError("Give the milestone a title.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      title: milestoneForm.title.trim(),
      description: milestoneForm.description.trim() || null,
      date: milestoneForm.date,
    };
    try {
      if (editingMilestone) {
        const res = await api.put<CareerMilestone>(`/learning/career-milestones/${editingMilestone.id}`, payload);
        setMilestones((prev) => prev.map((m) => (m.id === editingMilestone.id ? res.data : m)));
      } else {
        const res = await api.post<CareerMilestone>("/learning/career-milestones", payload);
        setMilestones((prev) => [res.data, ...prev]);
      }
      setMilestonePanel(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the milestone.");
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete() {
    if (!confirm) return;
    const { kind, id } = confirm;
    try {
      if (kind === "skill") {
        await api.delete(`/learning/skills/${id}`);
        setSkills((prev) => prev.filter((s) => s.id !== id));
      } else if (kind === "course") {
        await api.delete(`/learning/courses/${id}`);
        setCourses((prev) => prev.filter((c) => c.id !== id));
      } else {
        await api.delete(`/learning/career-milestones/${id}`);
        setMilestones((prev) => prev.filter((m) => m.id !== id));
      }
    } finally {
      setConfirm(null);
    }
  }

  const sortedMilestones = [...milestones].sort((a, b) => b.date.localeCompare(a.date));
  const completedCourses = courses.filter((c) => c.status === "completed").length;
  const avgProgress = courses.length ? Math.round(courses.reduce((acc, c) => acc + c.progress, 0) / courses.length) : 0;

  if (loading) {
    return (
      <div className="grid gap-4 lg:grid-cols-3">
        {[0, 1, 2].map((i) => (
          <Card key={i}>
            <LoadingBlock />
          </Card>
        ))}
      </div>
    );
  }
  if (error) return <ErrorBlock message={error} onRetry={load} />;

  return (
    <div className="space-y-5">
      <div className="grid gap-4 sm:grid-cols-3">
        <Card>
          <p className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Skills</p>
          <p className="mt-2 font-display text-[1.75rem] font-semibold leading-none text-ink">{skills.length}</p>
          <p className="mt-1 text-[0.8125rem] text-muted">being developed</p>
        </Card>
        <Card>
          <p className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Courses</p>
          <p className="mt-2 font-display text-[1.75rem] font-semibold leading-none text-ink">
            {completedCourses}/{courses.length}
          </p>
          <p className="mt-1 text-[0.8125rem] text-muted">completed · {avgProgress}% average progress</p>
        </Card>
        <Card>
          <p className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Milestones</p>
          <p className="mt-2 font-display text-[1.75rem] font-semibold leading-none text-ink">{milestones.length}</p>
          <p className="mt-1 text-[0.8125rem] text-muted">on your career timeline</p>
        </Card>
      </div>

      {/* Skills */}
      <Card>
        <CardHeader
          title="Skills"
          subtitle="Where you are today, on a 1 to 5 scale"
          action={
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                setEditingSkill(null);
                setSkillForm({ name: "", category: "", level: "1" });
                setFormError(null);
                setSkillPanel(true);
              }}
            >
              <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Add skill
            </Button>
          }
        />
        {skills.length === 0 ? (
          <EmptyState title="No skills listed" description="List the skills you are building and rate your level honestly." />
        ) : (
          <ul className="flex flex-wrap gap-2">
            {skills.map((skill) => (
              <li key={skill.id} className="rounded-lg border border-border px-3 py-2">
                <div className="flex items-center gap-2">
                  <span className="text-[0.875rem] font-medium text-ink">{skill.name}</span>
                  {skill.category && <Badge tone="neutral">{skill.category}</Badge>}
                  <div className="flex items-center gap-[2px]" aria-label={`Level ${skill.level} of 5`}>
                    {[1, 2, 3, 4, 5].map((n) => (
                      <span
                        key={n}
                        className={`h-1.5 w-1.5 rounded-full ${n <= skill.level ? "bg-primary" : "bg-surfaceMuted"}`}
                      />
                    ))}
                  </div>
                  <button
                    type="button"
                    onClick={() => {
                      setEditingSkill(skill);
                      setSkillForm({
                        name: skill.name,
                        category: skill.category ?? "",
                        level: String(skill.level),
                      });
                      setFormError(null);
                      setSkillPanel(true);
                    }}
                    aria-label={`Edit ${skill.name}`}
                    className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                  >
                    <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                  </button>
                  <button
                    type="button"
                    onClick={() => setConfirm({ kind: "skill", id: skill.id })}
                    aria-label={`Delete ${skill.name}`}
                    className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                  >
                    <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <div className="grid gap-4 lg:grid-cols-2">
        {/* Courses */}
        <Card>
          <CardHeader
            title="Courses"
            subtitle="What you are studying"
            action={
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setEditingCourse(null);
                  setCourseForm({ title: "", provider: "", status: "in_progress", progress: "0", target_date: "" });
                  setFormError(null);
                  setCoursePanel(true);
                }}
              >
                <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Add
              </Button>
            }
          />
          {courses.length === 0 ? (
            <EmptyState title="No courses" description="Add a course and track how far through it you are." />
          ) : (
            <ul className="space-y-3">
              {courses.map((course) => (
                <li key={course.id} className="rounded-lg border border-border p-3">
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <p className="truncate text-[0.9375rem] font-medium text-ink">{course.title}</p>
                      <p className="text-[0.75rem] text-muted">
                        {course.provider || "Self-study"}
                        {course.target_date ? ` · target ${format(new Date(`${course.target_date}T00:00:00`), "d MMM yyyy")}` : ""}
                      </p>
                    </div>
                    <div className="flex shrink-0 items-center gap-1">
                      <Badge tone={statusTone(course.status)}>{labelize(course.status)}</Badge>
                      <button
                        type="button"
                        onClick={() => {
                          setEditingCourse(course);
                          setCourseForm({
                            title: course.title,
                            provider: course.provider ?? "",
                            status: course.status,
                            progress: String(course.progress),
                            target_date: course.target_date ?? "",
                          });
                          setFormError(null);
                          setCoursePanel(true);
                        }}
                        aria-label={`Edit ${course.title}`}
                        className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                      >
                        <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                      <button
                        type="button"
                        onClick={() => setConfirm({ kind: "course", id: course.id })}
                        aria-label={`Delete ${course.title}`}
                        className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                      >
                        <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                    </div>
                  </div>
                  <div className="mt-2.5 h-2 w-full overflow-hidden rounded-full bg-surfaceMuted">
                    <div className="h-full rounded-full bg-primary" style={{ width: `${course.progress}%` }} />
                  </div>
                  <p className="mt-1.5 text-[0.75rem] text-muted">{course.progress}% complete</p>
                </li>
              ))}
            </ul>
          )}
        </Card>

        {/* Career timeline */}
        <Card>
          <CardHeader
            title="Career milestones"
            subtitle="A dated record of what you have achieved"
            action={
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setEditingMilestone(null);
                  setMilestoneForm({ title: "", description: "", date: todayISO });
                  setFormError(null);
                  setMilestonePanel(true);
                }}
              >
                <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Add
              </Button>
            }
          />
          {sortedMilestones.length === 0 ? (
            <EmptyState title="No milestones yet" description="Promotions, certifications, launches — record them here." />
          ) : (
            <ol className="relative space-y-4 border-l border-border pl-5">
              {sortedMilestones.map((m) => (
                <li key={m.id} className="relative">
                  <span
                    className="absolute -left-[26px] top-1.5 h-2.5 w-2.5 rounded-full bg-accent ring-4 ring-surface"
                    aria-hidden="true"
                  />
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <p className="text-[0.6875rem] uppercase tracking-wide text-muted">
                        {format(new Date(`${m.date}T00:00:00`), "MMM yyyy")}
                      </p>
                      <p className="text-[0.9375rem] font-medium text-ink">{m.title}</p>
                      {m.description && <p className="mt-0.5 text-[0.8125rem] text-muted">{m.description}</p>}
                    </div>
                    <div className="flex shrink-0 gap-1">
                      <button
                        type="button"
                        onClick={() => {
                          setEditingMilestone(m);
                          setMilestoneForm({
                            title: m.title,
                            description: m.description ?? "",
                            date: m.date,
                          });
                          setFormError(null);
                          setMilestonePanel(true);
                        }}
                        aria-label={`Edit ${m.title}`}
                        className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                      >
                        <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                      <button
                        type="button"
                        onClick={() => setConfirm({ kind: "milestone", id: m.id })}
                        aria-label={`Delete ${m.title}`}
                        className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                      >
                        <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                      </button>
                    </div>
                  </div>
                </li>
              ))}
            </ol>
          )}
        </Card>
      </div>

      {/* Skill panel */}
      <Modal
        open={skillPanel}
        onClose={() => setSkillPanel(false)}
        title={editingSkill ? "Edit skill" : "New skill"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setSkillPanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveSkill} loading={saving}>
              {editingSkill ? "Save changes" : "Add skill"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Skill name">
          <input
            className={inputClass}
            value={skillForm.name}
            onChange={(e) => setSkillForm({ ...skillForm, name: e.target.value })}
            placeholder="e.g. TypeScript"
          />
        </Field>
        <Field label="Category" hint="Optional — e.g. Engineering, Design, Leadership.">
          <input
            className={inputClass}
            value={skillForm.category}
            onChange={(e) => setSkillForm({ ...skillForm, category: e.target.value })}
          />
        </Field>
        <Field label="Level (1–5)">
          <select
            className={inputClass}
            value={skillForm.level}
            onChange={(e) => setSkillForm({ ...skillForm, level: e.target.value })}
          >
            {[1, 2, 3, 4, 5].map((n) => (
              <option key={n} value={String(n)}>
                {n}
              </option>
            ))}
          </select>
        </Field>
      </Modal>

      {/* Course panel */}
      <Modal
        open={coursePanel}
        onClose={() => setCoursePanel(false)}
        title={editingCourse ? "Edit course" : "New course"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setCoursePanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveCourse} loading={saving}>
              {editingCourse ? "Save changes" : "Add course"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Course title">
          <input
            className={inputClass}
            value={courseForm.title}
            onChange={(e) => setCourseForm({ ...courseForm, title: e.target.value })}
            placeholder="e.g. Advanced React Patterns"
          />
        </Field>
        <Field label="Provider" hint="Optional">
          <input
            className={inputClass}
            value={courseForm.provider}
            onChange={(e) => setCourseForm({ ...courseForm, provider: e.target.value })}
            placeholder="e.g. Frontend Masters"
          />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Status">
            <select
              className={inputClass}
              value={courseForm.status}
              onChange={(e) => setCourseForm({ ...courseForm, status: e.target.value as Course["status"] })}
            >
              <option value="planned">Planned</option>
              <option value="in_progress">In progress</option>
              <option value="completed">Completed</option>
            </select>
          </Field>
          <Field label="Progress %">
            <input
              type="number"
              min="0"
              max="100"
              className={inputClass}
              value={courseForm.progress}
              onChange={(e) => setCourseForm({ ...courseForm, progress: e.target.value })}
            />
          </Field>
        </div>
        <Field label="Target date" hint="Optional">
          <input
            type="date"
            className={inputClass}
            value={courseForm.target_date}
            onChange={(e) => setCourseForm({ ...courseForm, target_date: e.target.value })}
          />
        </Field>
      </Modal>

      {/* Milestone panel */}
      <Modal
        open={milestonePanel}
        onClose={() => setMilestonePanel(false)}
        title={editingMilestone ? "Edit milestone" : "New milestone"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setMilestonePanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveMilestone} loading={saving}>
              {editingMilestone ? "Save changes" : "Add milestone"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Title">
          <input
            className={inputClass}
            value={milestoneForm.title}
            onChange={(e) => setMilestoneForm({ ...milestoneForm, title: e.target.value })}
            placeholder="e.g. Promoted to senior engineer"
          />
        </Field>
        <Field label="Description" hint="Optional context">
          <textarea
            className={`${inputClass} min-h-[80px] resize-y`}
            value={milestoneForm.description}
            onChange={(e) => setMilestoneForm({ ...milestoneForm, description: e.target.value })}
          />
        </Field>
        <Field label="Date">
          <input
            type="date"
            className={inputClass}
            value={milestoneForm.date}
            onChange={(e) => setMilestoneForm({ ...milestoneForm, date: e.target.value })}
          />
        </Field>
      </Modal>

      <Modal
        open={confirm !== null}
        onClose={() => setConfirm(null)}
        title="Confirm delete"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirm(null)}>
              Cancel
            </Button>
            <Button variant="danger" onClick={handleDelete}>
              Delete
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">This entry will be permanently removed from your record.</p>
      </Modal>
    </div>
  );
}

import { useEffect, useState } from "react";
import { format } from "date-fns";
import { Plus, Pencil, Trash2 } from "lucide-react";
import { api } from "../lib/api";
import type { WellnessLog, Workout } from "../types";
import Card, { CardHeader } from "../components/ui/Card";
import StatCard from "../components/ui/StatCard";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

type WorkoutForm = {
  type: string;
  duration_minutes: string;
  calories: string;
  date: string;
  notes: string;
};

type WellnessForm = {
  date: string;
  mood: string;
  sleep_hours: string;
  water_glasses: string;
  weight: string;
};

const todayISO = format(new Date(), "yyyy-MM-dd");

interface FitnessSummary {
  workouts_this_week?: number;
  total_minutes?: number;
  total_calories?: number;
  avg_sleep_hours?: number;
  [key: string]: number | undefined;
}

export default function FitnessPage() {
  const [summary, setSummary] = useState<FitnessSummary | null>(null);
  const [workouts, setWorkouts] = useState<Workout[]>([]);
  const [wellness, setWellness] = useState<WellnessLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  const [workoutPanel, setWorkoutPanel] = useState(false);
  const [editingWorkout, setEditingWorkout] = useState<Workout | null>(null);
  const [workoutForm, setWorkoutForm] = useState<WorkoutForm>({
    type: "",
    duration_minutes: "30",
    calories: "",
    date: todayISO,
    notes: "",
  });

  const [wellnessPanel, setWellnessPanel] = useState(false);
  const [editingWellness, setEditingWellness] = useState<WellnessLog | null>(null);
  const [wellnessForm, setWellnessForm] = useState<WellnessForm>({
    date: todayISO,
    mood: "3",
    sleep_hours: "",
    water_glasses: "",
    weight: "",
  });

  const [confirm, setConfirm] = useState<{ kind: "workout" | "wellness"; id: number } | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const [s, w, wl] = await Promise.all([
        api.get<FitnessSummary>("/fitness/summary").catch(() => ({ data: {} as FitnessSummary })),
        api.get<Workout[]>("/fitness/workouts"),
        api.get<WellnessLog[]>("/fitness/wellness-logs"),
      ]);
      setSummary(s.data);
      setWorkouts(w.data);
      setWellness(wl.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your fitness record.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function saveWorkout() {
    if (!workoutForm.type.trim()) {
      setFormError("What kind of workout was it?");
      return;
    }
    const duration = Number(workoutForm.duration_minutes);
    if (!duration || duration <= 0) {
      setFormError("Enter a duration in minutes.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      type: workoutForm.type.trim(),
      duration_minutes: duration,
      calories: workoutForm.calories ? Number(workoutForm.calories) : null,
      date: workoutForm.date,
      notes: workoutForm.notes.trim() || null,
    };
    try {
      if (editingWorkout) {
        const res = await api.put<Workout>(`/fitness/workouts/${editingWorkout.id}`, payload);
        setWorkouts((prev) => prev.map((w) => (w.id === editingWorkout.id ? res.data : w)));
      } else {
        const res = await api.post<Workout>("/fitness/workouts", payload);
        setWorkouts((prev) => [res.data, ...prev]);
      }
      setWorkoutPanel(false);
      load();
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the workout.");
    } finally {
      setSaving(false);
    }
  }

  async function saveWellness() {
    setSaving(true);
    setFormError(null);
    const payload = {
      date: wellnessForm.date,
      mood: wellnessForm.mood ? Number(wellnessForm.mood) : null,
      sleep_hours: wellnessForm.sleep_hours ? Number(wellnessForm.sleep_hours) : null,
      water_glasses: wellnessForm.water_glasses ? Number(wellnessForm.water_glasses) : null,
      weight: wellnessForm.weight ? Number(wellnessForm.weight) : null,
    };
    try {
      if (editingWellness) {
        const res = await api.put<WellnessLog>(`/fitness/wellness-logs/${editingWellness.id}`, payload);
        setWellness((prev) => prev.map((w) => (w.id === editingWellness.id ? res.data : w)));
      } else {
        const res = await api.post<WellnessLog>("/fitness/wellness-logs", payload);
        setWellness((prev) => [res.data, ...prev]);
      }
      setWellnessPanel(false);
      load();
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the wellness log.");
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete() {
    if (!confirm) return;
    const { kind, id } = confirm;
    try {
      if (kind === "workout") {
        await api.delete(`/fitness/workouts/${id}`);
        setWorkouts((prev) => prev.filter((w) => w.id !== id));
      } else {
        await api.delete(`/fitness/wellness-logs/${id}`);
        setWellness((prev) => prev.filter((w) => w.id !== id));
      }
      load();
    } finally {
      setConfirm(null);
    }
  }

  const totalMinutes = summary?.total_minutes ?? workouts.reduce((acc, w) => acc + w.duration_minutes, 0);
  const totalCalories = summary?.total_calories ?? workouts.reduce((acc, w) => acc + (w.calories ?? 0), 0);
  const avgSleep =
    summary?.avg_sleep_hours ??
    (wellness.filter((w) => w.sleep_hours != null).length
      ? Math.round(
          (wellness.filter((w) => w.sleep_hours != null).reduce((a, w) => a + (w.sleep_hours ?? 0), 0) /
            wellness.filter((w) => w.sleep_hours != null).length) *
            10,
        ) / 10
      : 0);

  const sortedWorkouts = [...workouts].sort((a, b) => b.date.localeCompare(a.date));
  const sortedWellness = [...wellness].sort((a, b) => b.date.localeCompare(a.date));

  if (loading) {
    return (
      <div className="grid gap-4 md:grid-cols-4">
        {[0, 1, 2, 3].map((i) => (
          <Card key={i}>
            <LoadingBlock />
          </Card>
        ))}
      </div>
    );
  }
  if (error) return <ErrorBlock message={error} onRetry={load} />;

  return (
    <div className="space-y-5">
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Workouts" value={workouts.length} hint={`${summary?.workouts_this_week ?? 0} this week`} />
        <StatCard label="Minutes trained" value={totalMinutes} hint="all logged sessions" />
        <StatCard label="Calories burned" value={totalCalories || "—"} hint="where recorded" />
        <StatCard label="Average sleep" value={avgSleep ? `${avgSleep} h` : "—"} hint="from wellness logs" />
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <Card padding={false}>
          <div className="flex items-center justify-between gap-3 border-b border-border p-3">
            <h3 className="font-display text-[1.0625rem] font-semibold text-ink">Workouts</h3>
            <Button
              size="sm"
              onClick={() => {
                setEditingWorkout(null);
                setWorkoutForm({ type: "", duration_minutes: "30", calories: "", date: todayISO, notes: "" });
                setFormError(null);
                setWorkoutPanel(true);
              }}
            >
              <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Log workout
            </Button>
          </div>
          {sortedWorkouts.length === 0 ? (
            <div className="p-5">
              <EmptyState title="No workouts logged" description="Record a session — type, duration and calories." />
            </div>
          ) : (
            <ul className="divide-y divide-border">
              {sortedWorkouts.map((w) => (
                <li key={w.id} className="flex items-start justify-between gap-3 p-4">
                  <div className="min-w-0">
                    <p className="truncate text-[0.9375rem] font-medium text-ink">{w.type}</p>
                    <p className="text-[0.75rem] text-muted">
                      {format(new Date(`${w.date}T00:00:00`), "d MMM yyyy")} · {w.duration_minutes} min
                      {w.calories ? ` · ${w.calories} kcal` : ""}
                    </p>
                    {w.notes && <p className="mt-1 truncate text-[0.75rem] text-muted">{w.notes}</p>}
                  </div>
                  <div className="flex shrink-0 gap-1">
                    <button
                      type="button"
                      onClick={() => {
                        setEditingWorkout(w);
                        setWorkoutForm({
                          type: w.type,
                          duration_minutes: String(w.duration_minutes),
                          calories: w.calories != null ? String(w.calories) : "",
                          date: w.date,
                          notes: w.notes ?? "",
                        });
                        setFormError(null);
                        setWorkoutPanel(true);
                      }}
                      aria-label={`Edit ${w.type}`}
                      className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                    >
                      <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                    </button>
                    <button
                      type="button"
                      onClick={() => setConfirm({ kind: "workout", id: w.id })}
                      aria-label={`Delete ${w.type}`}
                      className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                    >
                      <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card padding={false}>
          <div className="flex items-center justify-between gap-3 border-b border-border p-3">
            <h3 className="font-display text-[1.0625rem] font-semibold text-ink">Wellness log</h3>
            <Button
              size="sm"
              onClick={() => {
                setEditingWellness(null);
                setWellnessForm({ date: todayISO, mood: "3", sleep_hours: "", water_glasses: "", weight: "" });
                setFormError(null);
                setWellnessPanel(true);
              }}
            >
              <Plus className="h-3.5 w-3.5" strokeWidth={2} /> Log day
            </Button>
          </div>
          {sortedWellness.length === 0 ? (
            <div className="p-5">
              <EmptyState title="No wellness entries" description="Track mood, sleep, water and weight day by day." />
            </div>
          ) : (
            <ul className="divide-y divide-border">
              {sortedWellness.map((w) => (
                <li key={w.id} className="flex items-start justify-between gap-3 p-4">
                  <div className="min-w-0">
                    <p className="text-[0.9375rem] font-medium text-ink">
                      {format(new Date(`${w.date}T00:00:00`), "EEEE d MMM")}
                    </p>
                    <p className="mt-0.5 flex flex-wrap gap-x-3 gap-y-0.5 text-[0.75rem] text-muted">
                      {w.mood != null && <span>Mood {w.mood}/5</span>}
                      {w.sleep_hours != null && <span>{w.sleep_hours} h sleep</span>}
                      {w.water_glasses != null && <span>{w.water_glasses} glasses</span>}
                      {w.weight != null && <span>{w.weight} kg</span>}
                    </p>
                  </div>
                  <div className="flex shrink-0 gap-1">
                    <button
                      type="button"
                      onClick={() => {
                        setEditingWellness(w);
                        setWellnessForm({
                          date: w.date,
                          mood: w.mood != null ? String(w.mood) : "3",
                          sleep_hours: w.sleep_hours != null ? String(w.sleep_hours) : "",
                          water_glasses: w.water_glasses != null ? String(w.water_glasses) : "",
                          weight: w.weight != null ? String(w.weight) : "",
                        });
                        setFormError(null);
                        setWellnessPanel(true);
                      }}
                      aria-label="Edit wellness entry"
                      className="rounded p-1 text-muted hover:bg-surfaceMuted hover:text-ink"
                    >
                      <Pencil className="h-3.5 w-3.5" strokeWidth={1.75} />
                    </button>
                    <button
                      type="button"
                      onClick={() => setConfirm({ kind: "wellness", id: w.id })}
                      aria-label="Delete wellness entry"
                      className="rounded p-1 text-muted hover:bg-danger/10 hover:text-danger"
                    >
                      <Trash2 className="h-3.5 w-3.5" strokeWidth={1.75} />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <Modal
        open={workoutPanel}
        onClose={() => setWorkoutPanel(false)}
        title={editingWorkout ? "Edit workout" : "Log a workout"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setWorkoutPanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveWorkout} loading={saving}>
              {editingWorkout ? "Save changes" : "Save workout"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Workout type">
          <input
            className={inputClass}
            value={workoutForm.type}
            onChange={(e) => setWorkoutForm({ ...workoutForm, type: e.target.value })}
            placeholder="e.g. Running, Strength, Yoga"
          />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Duration (minutes)">
            <input
              type="number"
              min="1"
              className={inputClass}
              value={workoutForm.duration_minutes}
              onChange={(e) => setWorkoutForm({ ...workoutForm, duration_minutes: e.target.value })}
            />
          </Field>
          <Field label="Calories" hint="Optional">
            <input
              type="number"
              min="0"
              className={inputClass}
              value={workoutForm.calories}
              onChange={(e) => setWorkoutForm({ ...workoutForm, calories: e.target.value })}
            />
          </Field>
        </div>
        <Field label="Date">
          <input
            type="date"
            className={inputClass}
            value={workoutForm.date}
            onChange={(e) => setWorkoutForm({ ...workoutForm, date: e.target.value })}
          />
        </Field>
        <Field label="Notes" hint="Optional">
          <textarea
            className={`${inputClass} min-h-[80px] resize-y`}
            value={workoutForm.notes}
            onChange={(e) => setWorkoutForm({ ...workoutForm, notes: e.target.value })}
          />
        </Field>
      </Modal>

      <Modal
        open={wellnessPanel}
        onClose={() => setWellnessPanel(false)}
        title={editingWellness ? "Edit wellness entry" : "Log your day"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setWellnessPanel(false)}>
              Cancel
            </Button>
            <Button onClick={saveWellness} loading={saving}>
              {editingWellness ? "Save changes" : "Save entry"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Date">
          <input
            type="date"
            className={inputClass}
            value={wellnessForm.date}
            onChange={(e) => setWellnessForm({ ...wellnessForm, date: e.target.value })}
          />
        </Field>
        <Field label="Mood (1–5)">
          <select
            className={inputClass}
            value={wellnessForm.mood}
            onChange={(e) => setWellnessForm({ ...wellnessForm, mood: e.target.value })}
          >
            {[1, 2, 3, 4, 5].map((n) => (
              <option key={n} value={String(n)}>
                {n}
              </option>
            ))}
          </select>
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Sleep (hours)">
            <input
              type="number"
              step="0.5"
              min="0"
              className={inputClass}
              value={wellnessForm.sleep_hours}
              onChange={(e) => setWellnessForm({ ...wellnessForm, sleep_hours: e.target.value })}
            />
          </Field>
          <Field label="Water (glasses)">
            <input
              type="number"
              min="0"
              className={inputClass}
              value={wellnessForm.water_glasses}
              onChange={(e) => setWellnessForm({ ...wellnessForm, water_glasses: e.target.value })}
            />
          </Field>
        </div>
        <Field label="Weight (kg)" hint="Optional">
          <input
            type="number"
            step="0.1"
            min="0"
            className={inputClass}
            value={wellnessForm.weight}
            onChange={(e) => setWellnessForm({ ...wellnessForm, weight: e.target.value })}
          />
        </Field>
      </Modal>

      <Modal
        open={confirm !== null}
        onClose={() => setConfirm(null)}
        title="Confirm delete"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirm(null)}>
              Cancel
            </Button>
            <Button variant="danger" onClick={handleDelete}>
              Delete
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">This entry will be permanently removed from your record.</p>
      </Modal>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  addDays,
  addMonths,
  endOfMonth,
  endOfWeek,
  format,
  isSameDay,
  isSameMonth,
  startOfMonth,
  startOfWeek,
  subMonths,
} from "date-fns";
import { ChevronLeft, ChevronRight, Plus, Pencil, Trash2, MapPin } from "lucide-react";
import { api } from "../lib/api";
import type { CalendarEvent } from "../types";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

type View = "month" | "week" | "agenda";

interface FormState {
  title: string;
  description: string;
  start_time: string;
  end_time: string;
  location: string;
  category: string;
}

function toLocalInput(d: Date) {
  return format(d, "yyyy-MM-dd'T'HH:mm");
}

const CATEGORY_TONES: Record<string, "primary" | "accent" | "success" | "warning" | "danger" | "neutral"> = {
  work: "primary",
  personal: "accent",
  health: "success",
  finance: "warning",
  general: "neutral",
};

export default function CalendarPage() {
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [cursor, setCursor] = useState(new Date());
  const [view, setView] = useState<View>("month");
  const [panelOpen, setPanelOpen] = useState(false);
  const [editing, setEditing] = useState<CalendarEvent | null>(null);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [confirmId, setConfirmId] = useState<number | null>(null);

  const [form, setForm] = useState<FormState>({
    title: "",
    description: "",
    start_time: toLocalInput(new Date()),
    end_time: toLocalInput(new Date(Date.now() + 60 * 60 * 1000)),
    location: "",
    category: "general",
  });

  async function load() {
    setLoading(true);
    setError(null);
    try {
      let start: Date;
      let end: Date;
      if (view === "week") {
        start = startOfWeek(cursor, { weekStartsOn: 1 });
        end = endOfWeek(cursor, { weekStartsOn: 1 });
      } else if (view === "month") {
        start = startOfWeek(startOfMonth(cursor), { weekStartsOn: 1 });
        end = endOfWeek(endOfMonth(cursor), { weekStartsOn: 1 });
      } else {
        start = startOfMonth(cursor);
        end = endOfMonth(cursor);
      }
      const res = await api.get<CalendarEvent[]>("/calendar/events", {
        params: {
          start: format(start, "yyyy-MM-dd"),
          end: format(end, "yyyy-MM-dd"),
        },
      });
      setEvents(res.data);
    } catch (err: any) {
      // fall back to all events if the range params are not supported
      try {
        const res = await api.get<CalendarEvent[]>("/calendar/events");
        setEvents(res.data);
      } catch (inner: any) {
        setError(inner?.response?.data?.detail || err?.response?.data?.detail || "Could not load your calendar.");
      }
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cursor, view]);

  function openCreate(startAt?: Date) {
    const base = startAt ?? new Date();
    setEditing(null);
    setForm({
      title: "",
      description: "",
      start_time: toLocalInput(base),
      end_time: toLocalInput(new Date(base.getTime() + 60 * 60 * 1000)),
      location: "",
      category: "general",
    });
    setFormError(null);
    setPanelOpen(true);
  }

  function openEdit(event: CalendarEvent) {
    setEditing(event);
    setForm({
      title: event.title,
      description: event.description ?? "",
      start_time: format(new Date(event.start_time), "yyyy-MM-dd'T'HH:mm"),
      end_time: format(new Date(event.end_time), "yyyy-MM-dd'T'HH:mm"),
      location: event.location ?? "",
      category: event.category,
    });
    setFormError(null);
    setPanelOpen(true);
  }

  async function handleSubmit() {
    if (!form.title.trim()) {
      setFormError("Give the event a title.");
      return;
    }
    if (new Date(form.end_time) <= new Date(form.start_time)) {
      setFormError("The end time must be after the start time.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const payload = {
      title: form.title.trim(),
      description: form.description.trim() || null,
      start_time: new Date(form.start_time).toISOString(),
      end_time: new Date(form.end_time).toISOString(),
      location: form.location.trim() || null,
      category: form.category.trim() || "general",
    };
    try {
      if (editing) {
        const res = await api.put<CalendarEvent>(`/calendar/events/${editing.id}`, payload);
        setEvents((prev) => prev.map((e) => (e.id === editing.id ? res.data : e)));
      } else {
        const res = await api.post<CalendarEvent>("/calendar/events", payload);
        setEvents((prev) => [...prev, res.data]);
      }
      setPanelOpen(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the event.");
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(id: number) {
    try {
      await api.delete(`/calendar/events/${id}`);
      setEvents((prev) => prev.filter((e) => e.id !== id));
    } finally {
      setConfirmId(null);
    }
  }

  const byDay = useMemo(() => {
    const map = new Map<string, CalendarEvent[]>();
    for (const e of events) {
      const key = format(new Date(e.start_time), "yyyy-MM-dd");
      const list = map.get(key) ?? [];
      list.push(e);
      map.set(key, list);
    }
    for (const list of map.values()) {
      list.sort((a, b) => a.start_time.localeCompare(b.start_time));
    }
    return map;
  }, [events]);

  const monthDays = useMemo(() => {
    const start = startOfWeek(startOfMonth(cursor), { weekStartsOn: 1 });
    const end = endOfWeek(endOfMonth(cursor), { weekStartsOn: 1 });
    const days: Date[] = [];
    let d = start;
    while (d <= end) {
      days.push(d);
      d = addDays(d, 1);
    }
    return days;
  }, [cursor]);

  const weekDays = useMemo(() => {
    const start = startOfWeek(cursor, { weekStartsOn: 1 });
    return Array.from({ length: 7 }, (_, i) => addDays(start, i));
  }, [cursor]);

  const agendaDays = useMemo(() => {
    const start = startOfMonth(cursor);
    const end = endOfMonth(cursor);
    const days: Date[] = [];
    let d = start;
    while (d <= end) {
      if (byDay.has(format(d, "yyyy-MM-dd"))) days.push(d);
      d = addDays(d, 1);
    }
    return days;
  }, [cursor, byDay]);

  const heading =
    view === "week"
      ? `${format(startOfWeek(cursor, { weekStartsOn: 1 }), "d MMM")} – ${format(
          endOfWeek(cursor, { weekStartsOn: 1 }),
          "d MMM yyyy",
        )}`
      : format(cursor, "MMMM yyyy");

  function shift(direction: -1 | 1) {
    if (view === "week") setCursor((c) => addDays(c, direction * 7));
    else setCursor((c) => addMonths(c, direction));
  }

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => shift(-1)}
            aria-label="Previous period"
            className="rounded-lg border border-border bg-surface p-1.5 text-ink hover:bg-surfaceMuted"
          >
            <ChevronLeft className="h-4 w-4" strokeWidth={1.75} />
          </button>
          <button
            type="button"
            onClick={() => shift(1)}
            aria-label="Next period"
            className="rounded-lg border border-border bg-surface p-1.5 text-ink hover:bg-surfaceMuted"
          >
            <ChevronRight className="h-4 w-4" strokeWidth={1.75} />
          </button>
          <button
            type="button"
            onClick={() => setCursor(new Date())}
            className="ml-1 rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[0.8125rem] text-ink hover:bg-surfaceMuted"
          >
            Today
          </button>
        </div>
        <h2 className="font-display text-[1.125rem] font-semibold text-ink">{heading}</h2>
        <div className="ml-auto flex items-center gap-2">
          <div className="flex rounded-lg border border-border bg-surface p-0.5">
            {(["month", "week", "agenda"] as View[]).map((v) => (
              <button
                key={v}
                type="button"
                onClick={() => setView(v)}
                className={`rounded-md px-2.5 py-1 text-[0.8125rem] capitalize transition-colors ${
                  view === v ? "bg-primary/10 font-medium text-primary" : "text-muted hover:text-ink"
                }`}
              >
                {v}
              </button>
            ))}
          </div>
          <Button onClick={() => openCreate()}>
            <Plus className="h-4 w-4" strokeWidth={2} /> New event
          </Button>
        </div>
      </div>

      {loading ? (
        <Card>
          <LoadingBlock label="Loading calendar" />
        </Card>
      ) : error ? (
        <ErrorBlock message={error} onRetry={load} />
      ) : view === "month" ? (
        <Card padding={false} className="overflow-hidden">
          <div className="grid grid-cols-7 border-b border-border bg-surfaceMuted/60">
            {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((d) => (
              <div key={d} className="px-2 py-1.5 text-[0.6875rem] font-semibold uppercase tracking-wide text-muted">
                {d}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7">
            {monthDays.map((day) => {
              const key = format(day, "yyyy-MM-dd");
              const list = byDay.get(key) ?? [];
              const outside = !isSameMonth(day, cursor);
              const isToday = isSameDay(day, new Date());
              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => openCreate(day)}
                  className={`min-h-[96px] border-b border-r border-border p-1.5 text-left align-top transition-colors last:border-r-0 hover:bg-surfaceMuted/50 ${
                    outside ? "bg-surfaceMuted/20" : "bg-surface"
                  }`}
                >
                  <span
                    className={`inline-flex h-6 w-6 items-center justify-center rounded-full text-[0.75rem] ${
                      isToday ? "bg-primary font-semibold text-primary-ink" : outside ? "text-muted/60" : "text-ink"
                    }`}
                  >
                    {format(day, "d")}
                  </span>
                  <div className="mt-1 space-y-1">
                    {list.slice(0, 2).map((e) => (
                      <span
                        key={e.id}
                        className="block truncate rounded bg-primary/10 px-1 py-0.5 text-[0.6875rem] text-primary"
                      >
                        {format(new Date(e.start_time), "HH:mm")} {e.title}
                      </span>
                    ))}
                    {list.length > 2 && (
                      <span className="block text-[0.6875rem] text-muted">+{list.length - 2} more</span>
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      ) : view === "week" ? (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7">
          {weekDays.map((day) => {
            const key = format(day, "yyyy-MM-dd");
            const list = byDay.get(key) ?? [];
            const isToday = isSameDay(day, new Date());
            return (
              <Card key={key} className={isToday ? "border-primary/40" : ""}>
                <p className="text-[0.6875rem] font-semibold uppercase tracking-wide text-muted">
                  {format(day, "EEE")}
                </p>
                <p className={`font-display text-[1.25rem] font-semibold ${isToday ? "text-primary" : "text-ink"}`}>
                  {format(day, "d MMM")}
                </p>
                {list.length === 0 ? (
                  <p className="mt-2 text-[0.75rem] text-muted">Nothing scheduled</p>
                ) : (
                  <ul className="mt-2 space-y-2">
                    {list.map((e) => (
                      <li key={e.id}>
                        <button
                          type="button"
                          onClick={() => openEdit(e)}
                          className="w-full rounded-lg border border-border px-2 py-1.5 text-left hover:bg-surfaceMuted"
                        >
                          <span className="block text-[0.6875rem] text-muted">
                            {format(new Date(e.start_time), "HH:mm")}
                          </span>
                          <span className="block truncate text-[0.8125rem] font-medium text-ink">{e.title}</span>
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </Card>
            );
          })}
        </div>
      ) : agendaDays.length === 0 ? (
        <EmptyState
          title="No events this month"
          description="Add an event and it will appear here, grouped by day."
          action={<Button onClick={() => openCreate()}>Add an event</Button>}
        />
      ) : (
        <div className="space-y-4">
          {agendaDays.map((day) => {
            const key = format(day, "yyyy-MM-dd");
            const list = byDay.get(key) ?? [];
            return (
              <Card key={key}>
                <div className="mb-3 flex items-baseline gap-2">
                  <h3 className="font-display text-[1.0625rem] font-semibold text-ink">{format(day, "EEEE d MMMM")}</h3>
                  <span className="text-[0.75rem] text-muted">{list.length} event{list.length === 1 ? "" : "s"}</span>
                </div>
                <ul className="divide-y divide-border">
                  {list.map((e) => (
                    <li key={e.id} className="flex items-start justify-between gap-3 py-2.5">
                      <div className="flex min-w-0 gap-3">
                        <div className="w-14 shrink-0 text-[0.75rem] text-muted">
                          {format(new Date(e.start_time), "HH:mm")}
                          <br />
                          {format(new Date(e.end_time), "HH:mm")}
                        </div>
                        <div className="min-w-0">
                          <p className="truncate text-[0.9375rem] font-medium text-ink">{e.title}</p>
                          {e.description && <p className="truncate text-[0.8125rem] text-muted">{e.description}</p>}
                          <div className="mt-1 flex flex-wrap items-center gap-2">
                            <Badge tone={CATEGORY_TONES[e.category] ?? "neutral"}>{e.category}</Badge>
                            {e.location && (
                              <span className="inline-flex items-center gap-1 text-[0.75rem] text-muted">
                                <MapPin className="h-3 w-3" strokeWidth={1.75} /> {e.location}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                      <div className="flex shrink-0 gap-1">
                        <button
                          type="button"
                          onClick={() => openEdit(e)}
                          aria-label={`Edit ${e.title}`}
                          className="rounded-lg p-1.5 text-muted hover:bg-surfaceMuted hover:text-ink"
                        >
                          <Pencil className="h-4 w-4" strokeWidth={1.75} />
                        </button>
                        <button
                          type="button"
                          onClick={() => setConfirmId(e.id)}
                          aria-label={`Delete ${e.title}`}
                          className="rounded-lg p-1.5 text-muted hover:bg-danger/10 hover:text-danger"
                        >
                          <Trash2 className="h-4 w-4" strokeWidth={1.75} />
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
              </Card>
            );
          })}
        </div>
      )}

      {!loading && !error && events.length > 0 && view === "month" && (
        <p className="text-[0.75rem] text-muted">Click any day to add an event. Events are listed by start time.</p>
      )}

      <Modal
        open={panelOpen}
        onClose={() => setPanelOpen(false)}
        title={editing ? "Edit event" : "New event"}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setPanelOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} loading={saving}>
              {editing ? "Save changes" : "Create event"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Title">
          <input
            className={inputClass}
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            placeholder="e.g. Dentist appointment"
          />
        </Field>
        <Field label="Description" hint="Optional">
          <textarea
            className={`${inputClass} min-h-[70px] resize-y`}
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Starts">
            <input
              type="datetime-local"
              className={inputClass}
              value={form.start_time}
              onChange={(e) => setForm({ ...form, start_time: e.target.value })}
            />
          </Field>
          <Field label="Ends">
            <input
              type="datetime-local"
              className={inputClass}
              value={form.end_time}
              onChange={(e) => setForm({ ...form, end_time: e.target.value })}
            />
          </Field>
        </div>
        <Field label="Location" hint="Optional">
          <input
            className={inputClass}
            value={form.location}
            onChange={(e) => setForm({ ...form, location: e.target.value })}
            placeholder="Where is it?"
          />
        </Field>
        <Field label="Category">
          <select
            className={inputClass}
            value={form.category}
            onChange={(e) => setForm({ ...form, category: e.target.value })}
          >
            <option value="general">General</option>
            <option value="work">Work</option>
            <option value="personal">Personal</option>
            <option value="health">Health</option>
            <option value="finance">Finance</option>
          </select>
        </Field>
      </Modal>

      <Modal
        open={confirmId !== null}
        onClose={() => setConfirmId(null)}
        title="Delete event"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirmId(null)}>
              Keep it
            </Button>
            <Button variant="danger" onClick={() => confirmId !== null && handleDelete(confirmId)}>
              Delete event
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">This event will be removed from your calendar.</p>
      </Modal>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { format } from "date-fns";
import { Plus, Pencil, Trash2 } from "lucide-react";
import { api } from "../lib/api";
import type { Goal } from "../types";
import Card from "../components/ui/Card";
import StatCard from "../components/ui/StatCard";
import Badge, { labelize, statusTone } from "../components/ui/Badge";
import Button from "../components/ui/Button";
import Modal, { Field, inputClass } from "../components/ui/Modal";
import EmptyState, { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

const CATEGORIES: Goal["category"][] = ["career", "finance", "health", "learning", "personal"];

interface FormState {
  title: string;
  category: Goal["category"];
  description: string;
  target_date: string;
  progress: string;
  status: Goal["status"];
}

const emptyForm: FormState = {
  title: "",
  category: "personal",
  description: "",
  target_date: "",
  progress: "0",
  status: "active",
};

function progressTone(progress: number, status: Goal["status"]) {
  if (status === "completed" || progress >= 100) return "bg-success";
  if (status === "abandoned") return "bg-muted";
  if (progress >= 60) return "bg-accent";
  return "bg-primary";
}

export default function GoalsPage() {
  const [goals, setGoals] = useState<Goal[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const [editing, setEditing] = useState<Goal | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [confirmId, setConfirmId] = useState<number | null>(null);
  const [categoryFilter, setCategoryFilter] = useState<string>("all");

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const res = await api.get<Goal[]>("/goals");
      setGoals(res.data);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load your goals.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setFormError(null);
    setPanelOpen(true);
  }

  function openEdit(goal: Goal) {
    setEditing(goal);
    setForm({
      title: goal.title,
      category: goal.category,
      description: goal.description ?? "",
      target_date: goal.target_date ?? "",
      progress: String(goal.progress),
      status: goal.status,
    });
    setFormError(null);
    setPanelOpen(true);
  }

  async function handleSubmit() {
    if (!form.title.trim()) {
      setFormError("Give the goal a title.");
      return;
    }
    setSaving(true);
    setFormError(null);
    const progress = Math.min(100, Math.max(0, Number(form.progress) || 0));
    const payload = {
      title: form.title.trim(),
      category: form.category,
      description: form.description.trim() || null,
      target_date: form.target_date || null,
      progress,
      status: progress >= 100 ? "completed" : form.status,
    };
    try {
      if (editing) {
        const res = await api.put<Goal>(`/goals/${editing.id}`, payload);
        setGoals((prev) => prev.map((g) => (g.id === editing.id ? res.data : g)));
      } else {
        const res = await api.post<Goal>("/goals", payload);
        setGoals((prev) => [res.data, ...prev]);
      }
      setPanelOpen(false);
    } catch (err: any) {
      setFormError(err?.response?.data?.detail || "Could not save the goal.");
    } finally {
      setSaving(false);
    }
  }

  async function quickProgress(goal: Goal, delta: number) {
    const progress = Math.min(100, Math.max(0, goal.progress + delta));
    const optimistic = { ...goal, progress, status: progress >= 100 ? ("completed" as const) : goal.status };
    setGoals((prev) => prev.map((g) => (g.id === goal.id ? optimistic : g)));
    try {
      const res = await api.put<Goal>(`/goals/${goal.id}`, {
        title: goal.title,
        category: goal.category,
        description: goal.description,
        target_date: goal.target_date,
        progress,
        status: progress >= 100 ? "completed" : goal.status,
      });
      setGoals((prev) => prev.map((g) => (g.id === goal.id ? res.data : g)));
    } catch {
      setGoals((prev) => prev.map((g) => (g.id === goal.id ? goal : g)));
    }
  }

  async function handleDelete(id: number) {
    try {
      await api.delete(`/goals/${id}`);
      setGoals((prev) => prev.filter((g) => g.id !== id));
    } finally {
      setConfirmId(null);
    }
  }

  const visible = useMemo(
    () => (categoryFilter === "all" ? goals : goals.filter((g) => g.category === categoryFilter)),
    [goals, categoryFilter],
  );

  const activeCount = goals.filter((g) => g.status === "active").length;
  const completedCount = goals.filter((g) => g.status === "completed").length;
  const avgProgress = goals.length ? Math.round(goals.reduce((a, g) => a + g.progress, 0) / goals.length) : 0;

  if (loading) {
    return (
      <div className="grid gap-4 md:grid-cols-3">
        {[0, 1, 2].map((i) => (
          <Card key={i}>
            <LoadingBlock />
          </Card>
        ))}
      </div>
    );
  }
  if (error) return <ErrorBlock message={error} onRetry={load} />;

  return (
    <div className="space-y-5">
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Active goals" value={activeCount} hint="in progress" />
        <StatCard label="Completed" value={completedCount} hint="reached the target" />
        <StatCard label="Average progress" value={`${avgProgress}%`} hint="across all goals" />
        <StatCard label="Total goals" value={goals.length} hint="in your workspace" />
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <div className="flex flex-wrap gap-1.5">
          {["all", ...CATEGORIES].map((c) => (
            <button
              key={c}
              type="button"
              onClick={() => setCategoryFilter(c)}
              className={`rounded-full px-3 py-1 text-[0.8125rem] capitalize transition-colors ${
                categoryFilter === c
                  ? "bg-primary/10 font-medium text-primary"
                  : "border border-border bg-surface text-muted hover:text-ink"
              }`}
            >
              {c}
            </button>
          ))}
        </div>
        <Button className="ml-auto" onClick={openCreate}>
          <Plus className="h-4 w-4" strokeWidth={2} /> New goal
        </Button>
      </div>

      {visible.length === 0 ? (
        <EmptyState
          title={goals.length === 0 ? "No goals yet" : "No goals in this category"}
          description={
            goals.length === 0
              ? "Set yourself something to work towards — career, finance, health, learning or personal."
              : "Switch category or add a goal here."
          }
          action={<Button onClick={openCreate}>Add a goal</Button>}
        />
      ) : (
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {visible.map((goal) => (
            <Card key={goal.id} className="flex flex-col">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <h3 className="truncate font-display text-[1.0625rem] font-semibold text-ink">{goal.title}</h3>
                  <div className="mt-1 flex flex-wrap items-center gap-1.5">
                    <Badge tone="accent">{labelize(goal.category)}</Badge>
                    <Badge tone={statusTone(goal.status)}>{labelize(goal.status)}</Badge>
                  </div>
                </div>
                <div className="flex shrink-0 gap-1">
                  <button
                    type="button"
                    onClick={() => openEdit(goal)}
                    aria-label={`Edit ${goal.title}`}
                    className="rounded-lg p-1.5 text-muted hover:bg-surfaceMuted hover:text-ink"
                  >
                    <Pencil className="h-4 w-4" strokeWidth={1.75} />
                  </button>
                  <button
                    type="button"
                    onClick={() => setConfirmId(goal.id)}
                    aria-label={`Delete ${goal.title}`}
                    className="rounded-lg p-1.5 text-muted hover:bg-danger/10 hover:text-danger"
                  >
                    <Trash2 className="h-4 w-4" strokeWidth={1.75} />
                  </button>
                </div>
              </div>

              {goal.description && (
                <p className="mt-2 line-clamp-2 text-[0.875rem] leading-relaxed text-muted">{goal.description}</p>
              )}

              <div className="mt-auto pt-4">
                <div className="flex items-center justify-between text-[0.75rem] text-muted">
                  <span>{goal.progress}% complete</span>
                  {goal.target_date && (
                    <span>target {format(new Date(`${goal.target_date}T00:00:00`), "d MMM yyyy")}</span>
                  )}
                </div>
                <div className="mt-1.5 h-2 w-full overflow-hidden rounded-full bg-surfaceMuted">
                  <div
                    className={`h-full rounded-full ${progressTone(goal.progress, goal.status)}`}
                    style={{ width: `${goal.progress}%` }}
                  />
                </div>
                <div className="mt-3 flex items-center gap-1.5">
                  <Button variant="secondary" size="sm" onClick={() => quickProgress(goal, -10)} disabled={goal.progress <= 0}>
                    −10
                  </Button>
                  <Button variant="secondary" size="sm" onClick={() => quickProgress(goal, 10)} disabled={goal.progress >= 100}>
                    +10
                  </Button>
                  <span className="ml-auto text-[0.6875rem] text-muted">Adjust progress</span>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}

      <Modal
        open={panelOpen}
        onClose={() => setPanelOpen(false)}
        title={editing ? "Edit goal" : "New goal"}
        subtitle="Set a target and keep the progress honest."
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setPanelOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} loading={saving}>
              {editing ? "Save changes" : "Create goal"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-[0.8125rem] text-danger">
            {formError}
          </div>
        )}
        <Field label="Goal title">
          <input
            className={inputClass}
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            placeholder="e.g. Build a three-month emergency fund"
          />
        </Field>
        <Field label="Category">
          <select
            className={inputClass}
            value={form.category}
            onChange={(e) => setForm({ ...form, category: e.target.value as Goal["category"] })}
          >
            {CATEGORIES.map((c) => (
              <option key={c} value={c}>
                {labelize(c)}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Description" hint="Optional">
          <textarea
            className={`${inputClass} min-h-[90px] resize-y`}
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
            placeholder="What does done look like?"
          />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Target date" hint="Optional">
            <input
              type="date"
              className={inputClass}
              value={form.target_date}
              onChange={(e) => setForm({ ...form, target_date: e.target.value })}
            />
          </Field>
          <Field label="Status">
            <select
              className={inputClass}
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value as Goal["status"] })}
            >
              <option value="active">Active</option>
              <option value="completed">Completed</option>
              <option value="abandoned">Abandoned</option>
            </select>
          </Field>
        </div>
        <Field label={`Progress — ${form.progress}%`}>
          <input
            type="range"
            min="0"
            max="100"
            step="5"
            value={form.progress}
            onChange={(e) => setForm({ ...form, progress: e.target.value })}
            className="w-full accent-[var(--primary)]"
            aria-label="Goal progress"
          />
        </Field>
      </Modal>

      <Modal
        open={confirmId !== null}
        onClose={() => setConfirmId(null)}
        title="Delete goal"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="secondary" onClick={() => setConfirmId(null)}>
              Keep it
            </Button>
            <Button variant="danger" onClick={() => confirmId !== null && handleDelete(confirmId)}>
              Delete goal
            </Button>
          </div>
        }
      >
        <p className="text-[0.875rem] text-muted">This goal will be permanently removed from your workspace.</p>
      </Modal>
    </div>
  );
}

import { FormEvent, useEffect, useState } from "react";
import { format } from "date-fns";
import { api } from "../lib/api";
import { useAuth } from "../context/AuthContext";
import Card, { CardHeader } from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Button from "../components/ui/Button";
import { Field, inputClass } from "../components/ui/Modal";
import { PasswordInput } from "./Login";

export default function SettingsPage() {
  const { user, refreshUser } = useAuth();
  const [name, setName] = useState(user?.name ?? "");
  const [email, setEmail] = useState(user?.email ?? "");
  const [profileSaving, setProfileSaving] = useState(false);
  const [profileMsg, setProfileMsg] = useState<{ type: "ok" | "err"; text: string } | null>(null);

  const [oldPassword, setOldPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [pwSaving, setPwSaving] = useState(false);
  const [pwMsg, setPwMsg] = useState<{ type: "ok" | "err"; text: string } | null>(null);

  useEffect(() => {
    setName(user?.name ?? "");
    setEmail(user?.email ?? "");
  }, [user]);

  async function saveProfile(e: FormEvent) {
    e.preventDefault();
    setProfileMsg(null);
    if (!name.trim() || !email.trim()) {
      setProfileMsg({ type: "err", text: "Name and email are both required." });
      return;
    }
    setProfileSaving(true);
    try {
      await api.put("/settings/profile", { name: name.trim(), email: email.trim() });
      await refreshUser();
      setProfileMsg({ type: "ok", text: "Profile updated." });
    } catch (err: any) {
      setProfileMsg({
        type: "err",
        text: err?.response?.data?.detail || "Could not update your profile.",
      });
    } finally {
      setProfileSaving(false);
    }
  }

  async function savePassword(e: FormEvent) {
    e.preventDefault();
    setPwMsg(null);
    if (newPassword.length < 6) {
      setPwMsg({ type: "err", text: "The new password must be at least 6 characters." });
      return;
    }
    if (newPassword !== confirmPassword) {
      setPwMsg({ type: "err", text: "The new passwords do not match." });
      return;
    }
    setPwSaving(true);
    try {
      await api.put("/settings/password", { old_password: oldPassword, new_password: newPassword });
      setPwMsg({ type: "ok", text: "Password changed." });
      setOldPassword("");
      setNewPassword("");
      setConfirmPassword("");
    } catch (err: any) {
      setPwMsg({
        type: "err",
        text: err?.response?.data?.detail || "Could not change your password.",
      });
    } finally {
      setPwSaving(false);
    }
  }

  return (
    <div className="max-w-3xl space-y-5">
      <Card>
        <CardHeader title="Your account" subtitle="Details attached to your private workspace" />
        <dl className="grid gap-3 sm:grid-cols-2">
          <div>
            <dt className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Name</dt>
            <dd className="mt-1 text-[0.9375rem] text-ink">{user?.name}</dd>
          </div>
          <div>
            <dt className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Email</dt>
            <dd className="mt-1 text-[0.9375rem] text-ink">{user?.email}</dd>
          </div>
          <div>
            <dt className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Role</dt>
            <dd className="mt-1">
              <Badge tone={user?.role === "OWNER" ? "primary" : "neutral"}>{user?.role ?? "USER"}</Badge>
            </dd>
          </div>
          <div>
            <dt className="text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted">Member since</dt>
            <dd className="mt-1 text-[0.9375rem] text-ink">
              {user?.created_at ? format(new Date(user.created_at), "d MMMM yyyy") : "—"}
            </dd>
          </div>
        </dl>
      </Card>

      <Card>
        <CardHeader title="Edit profile" subtitle="Change the name and email shown across your workspace" />
        <form onSubmit={saveProfile}>
          {profileMsg && (
            <div
              className={`mb-4 rounded-lg border px-3 py-2 text-[0.8125rem] ${
                profileMsg.type === "ok"
                  ? "border-success/30 bg-success/5 text-success"
                  : "border-danger/30 bg-danger/5 text-danger"
              }`}
            >
              {profileMsg.text}
            </div>
          )}
          <Field label="Full name">
            <input className={inputClass} value={name} onChange={(e) => setName(e.target.value)} autoComplete="name" />
          </Field>
          <Field label="Email">
            <input
              type="email"
              className={inputClass}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              autoComplete="email"
            />
          </Field>
          <Button type="submit" loading={profileSaving}>
            Save profile
          </Button>
        </form>
      </Card>

      <Card>
        <CardHeader title="Change password" subtitle="Use at least 6 characters" />
        <form onSubmit={savePassword}>
          {pwMsg && (
            <div
              className={`mb-4 rounded-lg border px-3 py-2 text-[0.8125rem] ${
                pwMsg.type === "ok"
                  ? "border-success/30 bg-success/5 text-success"
                  : "border-danger/30 bg-danger/5 text-danger"
              }`}
            >
              {pwMsg.text}
            </div>
          )}
          <Field label="Current password">
            <PasswordInput
              id="settings-current-password"
              value={oldPassword}
              onChange={setOldPassword}
              placeholder="Your current password"
              autoComplete="current-password"
            />
          </Field>
          <Field label="New password">
            <PasswordInput
              id="settings-new-password"
              value={newPassword}
              onChange={setNewPassword}
              placeholder="At least 6 characters"
              autoComplete="new-password"
            />
          </Field>
          <Field label="Confirm new password">
            <PasswordInput
              id="settings-confirm-password"
              value={confirmPassword}
              onChange={setConfirmPassword}
              placeholder="Repeat the new password"
              autoComplete="new-password"
            />
          </Field>
          <Button type="submit" loading={pwSaving}>
            Update password
          </Button>
        </form>
      </Card>

      <Card>
        <CardHeader title="Privacy" subtitle="How your data is handled" />
        <p className="text-[0.875rem] leading-relaxed text-muted">
          Everything you record in Life OS is attached to your own account. Tasks, transactions, habits, workouts,
          events and goals are queried only for the signed-in user, so no other person can see your workspace.
          Nothing is generated, inferred or automated — the numbers you see are arithmetic on the entries you made.
        </p>
      </Card>
    </div>
  );
}

import { ChangeEvent, FormEvent, useEffect, useState } from "react";
import { api } from "../lib/api";
import type { SiteSettings } from "../types";
import Card, { CardHeader } from "../components/ui/Card";
import Button from "../components/ui/Button";
import { Field, inputClass } from "../components/ui/Modal";
import { ErrorBlock, LoadingBlock } from "../components/ui/EmptyState";

export default function AdminSettingsPage() {
  const [site, setSite] = useState<SiteSettings | null>(null);
  const [title, setTitle] = useState("");
  const [tagline, setTagline] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<{ type: "ok" | "err"; text: string } | null>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState<{ type: "ok" | "err"; text: string } | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const res = await api.get<SiteSettings>("/settings/site");
      setSite(res.data);
      setTitle(res.data.site_title);
      setTagline(res.data.tagline);
    } catch (err: any) {
      setError(err?.response?.data?.detail || "Could not load site settings.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function saveSite(e: FormEvent) {
    e.preventDefault();
    setMsg(null);
    if (!title.trim()) {
      setMsg({ type: "err", text: "The site title cannot be empty." });
      return;
    }
    setSaving(true);
    try {
      const res = await api.put<SiteSettings>("/settings/site", {
        site_title: title.trim(),
        tagline: tagline.trim(),
      });
      setSite(res.data);
      setTitle(res.data.site_title);
      setTagline(res.data.tagline);
      setMsg({ type: "ok", text: "Site settings saved — the public pages now use these values." });
      document.title = res.data.site_title;
    } catch (err: any) {
      setMsg({ type: "err", text: err?.response?.data?.detail || "Could not save site settings." });
    } finally {
      setSaving(false);
    }
  }

  async function uploadLogo(e: ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    setUploadMsg(null);
    const data = new FormData();
    data.append("file", file);
    try {
      const res = await api.post<SiteSettings>("/settings/site/logo", data, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setSite(res.data);
      setUploadMsg({ type: "ok", text: "Logo uploaded." });
    } catch (err: any) {
      setUploadMsg({ type: "err", text: err?.response?.data?.detail || "Could not upload the logo." });
    } finally {
      setUploading(false);
      e.target.value = "";
    }
  }

  if (loading) {
    return (
      <Card>
        <LoadingBlock label="Loading site settings" />
      </Card>
    );
  }
  if (error) return <ErrorBlock message={error} onRetry={load} />;

  return (
    <div className="max-w-3xl space-y-5">
      <Card>
        <CardHeader
          title="Branding"
          subtitle="The name and tagline shown on the public site, sign-in screens and app navigation"
        />
        <form onSubmit={saveSite}>
          {msg && (
            <div
              className={`mb-4 rounded-lg border px-3 py-2 text-[0.8125rem] ${
                msg.type === "ok"
                  ? "border-success/30 bg-success/5 text-success"
                  : "border-danger/30 bg-danger/5 text-danger"
              }`}
            >
              {msg.text}
            </div>
          )}
          <Field label="Site title">
            <input className={inputClass} value={title} onChange={(e) => setTitle(e.target.value)} />
          </Field>
          <Field label="Tagline" hint="One line describing the product.">
            <input className={inputClass} value={tagline} onChange={(e) => setTagline(e.target.value)} />
          </Field>
          <Button type="submit" loading={saving}>
            Save changes
          </Button>
        </form>
      </Card>

      <Card>
        <CardHeader title="Logo" subtitle="PNG, SVG or WebP — a transparent PNG works best" />
        {uploadMsg && (
          <div
            className={`mb-4 rounded-lg border px-3 py-2 text-[0.8125rem] ${
              uploadMsg.type === "ok"
                ? "border-success/30 bg-success/5 text-success"
                : "border-danger/30 bg-danger/5 text-danger"
            }`}
          >
            {uploadMsg.text}
          </div>
        )}
        <div className="flex flex-wrap items-center gap-5">
          <div className="flex h-20 w-20 items-center justify-center overflow-hidden rounded-xl border border-border bg-surfaceMuted">
            {site?.logo_url ? (
              <img src={site.logo_url} alt="Current site logo" className="h-full w-full object-contain p-2" />
            ) : (
              <span className="font-display text-[0.75rem] text-muted">No logo</span>
            )}
          </div>
          <div>
            <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-border bg-surface px-4 py-2 text-[0.875rem] font-medium text-ink transition-colors hover:bg-surfaceMuted">
              {uploading ? "Uploading…" : "Choose file"}
              <input
                type="file"
                accept="image/png,image/jpeg,image/webp,image/svg+xml"
                onChange={uploadLogo}
                disabled={uploading}
                className="sr-only"
              />
            </label>
            <p className="mt-2 text-[0.75rem] text-muted">
              The uploaded logo replaces the current one everywhere the brand appears.
            </p>
          </div>
        </div>
      </Card>

      <Card>
        <CardHeader title="Preview" subtitle="How the brand renders in the app header" />
        <div className="flex items-center gap-2.5 rounded-lg border border-border bg-bg px-4 py-3">
          {site?.logo_url ? (
            <img src={site.logo_url} alt="" className="h-7 w-7 rounded-lg object-contain" />
          ) : (
            <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-primary font-display text-[0.8125rem] font-bold text-primary-ink">
              L
            </span>
          )}
          <div>
            <p className="font-display text-[1rem] font-semibold leading-tight text-ink">{site?.site_title}</p>
            <p className="text-[0.6875rem] text-muted">{site?.tagline}</p>
          </div>
        </div>
      </Card>
    </div>
  );
}
